        // ======================= VERSIONNAGE DE L'APPLICATION =======================
        // Convention : MAJEUR.MINEUR.CORRECTIF — le mineur augmente à chaque évolution
        // fonctionnelle, le majeur pour les refontes d'ampleur, le correctif pour les corrections.
        // La cible V11 (fichier séparé, voir manifest-v11.json) fournit sa propre version et ses entrées de journal.
        const APP_VERSION = (typeof V13_VERSION !== 'undefined') ? V13_VERSION : ((typeof V12_VERSION !== 'undefined') ? V12_VERSION : ((typeof V11_VERSION !== 'undefined') ? V11_VERSION : '10.2.3'));
        // V9.2.1 : le titre de l'onglet suit la version, plus jamais un numéro figé (« V5 »).
        try { document.title = 'Studio Data ' + APP_VERSION; } catch (e) {}
        const APP_CHANGELOG = [
            ...((typeof V13_CHANGELOG !== 'undefined') ? V13_CHANGELOG : []),
            ...((typeof V12_CHANGELOG !== 'undefined') ? V12_CHANGELOG : []),
            ...((typeof V11_CHANGELOG !== 'undefined') ? V11_CHANGELOG : []),
            { v: '10.2.3', d: '2026-09-09', t: 'Chaîne de construction : troisième cible StudioDataV12.html', items: [
                'Aucun changement fonctionnel. Trois fichiers peuvent être assemblés : V7 (inchangé), V11 (ergonomie de la gouvernance) et V12 (ergonomie de toute l\'application).'] },
            { v: '10.2.2', d: '2026-09-08', t: 'Chaîne de construction : deuxième cible StudioDataV11.html', items: [
                'Aucun changement fonctionnel. Les sources peuvent désormais être assemblées en deux fichiers : StudioDataV7.html (inchangé) et StudioDataV11.html (couche ergonomique V11).'] },
            { v: '10.2.1', d: '2026-09-08', t: 'Ce qu\'on ne peut pas modifier est grisé', items: [
                'Quand le profil actif n\'a ni rôle de propriétaire ni rôle de contributeur sur un élément, sa fiche devient <b>inerte</b> : bandeau « 🔒 Lecture seule », champs, listes et boutons grisés et désactivés. Fiche objet (et son dictionnaire par objet), fiche terme, fiche application ou processus, table du dictionnaire.',
                'Pour un contributeur, les champs réservés (<b>propriétaire</b>, <b>domaine métier</b>) sont grisés de la même façon, avec l\'indication « réservé au propriétaire », au lieu d\'un message après coup.'] },
            { v: '10.2.0', d: '2026-09-08', t: 'Le contributeur peut tout proposer, sauf le propriétaire et le domaine', items: [
                'Un contributeur propose désormais aussi la <b>structure</b> : nom d\'un attribut, colonne rattachée, ajout ou suppression d\'attributs, facettes, sources et leurs rôles, applications, hiérarchies, règles, statut, suppression de l\'objet… L\'opération est exécutée sur une copie, la différence est enregistrée comme proposition, l\'objet reste intact jusqu\'à la validation.',
                'Les propositions de structure apparaissent dans la fiche de l\'objet (« Propositions de structure en attente ») avec ce qui change (+ ajouts, − retraits) et dans « À valider », où le propriétaire valide ou refuse ; l\'application d\'une validation est tracée dans l\'historique.',
                'Seuls le <b>propriétaire</b> et le <b>domaine métier</b> restent réservés au propriétaire : ces champs sont verrouillés (🔒) pour un contributeur au lieu de rebondir. Cela vaut pour les objets, les termes, les applications (responsable, domaine) et les sources (propriétaire, domaine).',
                'Applications et processus : description, criticité, sources, colonnes et liens passent par les propositions au lieu d\'être refusés.'] },
            { v: '10.1.1', d: '2026-09-08', t: 'Domaines métier : choix possible par tous, suppression propre', items: [
                'Choisir un <b>domaine</b> sur un objet, un terme, une application ou une source ne « rebondit » plus : quand le profil actif est contributeur, le changement devient une <b>proposition</b> (pastille ⏳ à côté du sélecteur), validée par le propriétaire du domaine actuel. Auparavant il était refusé avec un simple message.',
                'Écran Acteurs : chaque domaine affiche ce qui l\'utilise (sources, objets, termes, applis, rôles) et un <b>✕ pour le supprimer</b> partout après confirmation.',
                'Le <b>dictionnaire</b> permet de choisir le domaine métier d\'une source (son thème) directement dans la fiche de la table ; la liste de domaines des applications reprend tous les domaines déclarés.'] },
            { v: '10.1.0', d: '2026-09-08', t: 'Rôles et validation appliqués à vos données, plus seulement à un scénario', items: [
                'Le <b>propriétaire nommé sur un objet</b> (champ « Propriétaire global », désormais relié aux personnes déclarées) <b>valide cet objet</b>, quel que soit son rôle sur le domaine : la fiche indique « 👑 personne reconnue : elle valide cet objet ».',
                'Le <b>dictionnaire par table technique</b> passe aussi par les propositions : définition, exemples, sensibilité, terme d\'une colonne, description et propriétaire d\'une source. Le domaine d\'une source est son thème ; les propositions se groupent par table dans « À valider » et « Voir » ouvre le dictionnaire sur la bonne table.',
                'L\'exemple de rôles (bouton « Exemple de rôles ») crée quatre personnes sur tous les domaines <b>sans toucher à vos objets, termes ou sources</b> — renommez-les ou remplacez-les par les vôtres. Le vocabulaire « démonstrateur » disparaît de l\'interface.'] },
            { v: '10.0.0', d: '2026-09-08', t: 'Personnes, rôles par domaine et circuit de validation (démonstrateur)', items: [
                'Nouvel écran <b>Personnes & rôles</b> : chaque personne reçoit un ou plusieurs couples <b>domaine métier → rôle</b> — <b>Propriétaire</b> (modifie et valide), <b>Contributeur</b> (propose), <b>Lecteur</b> (consulte), plus un administrateur « tous domaines ». Un bouton <b>🎬 Jeu de démonstration</b> crée Alice, Bob, Chloé et un admin sur le premier domaine.',
                'Sélecteur <b>« Vous êtes »</b> dans l\'en-tête : on change de personne d\'un clic (profil actif déclaratif, mono-poste — pas une authentification). Un lecteur passe automatiquement en mode consultation.',
                'Un <b>contributeur</b> travaille dans les écrans habituels, mais ses modifications de sens (définition, exemples, sensibilité, propriétaire, nombre de valeurs, termes posés ou retirés, définition d\'un terme, description d\'une application) deviennent des <b>propositions</b> : la valeur en vigueur reste, la proposition s\'affiche à côté en orange « ⏳ Bob propose : … ». La structure (attributs, colonnes, facettes) reste réservée au propriétaire.',
                'Écran <b>✅ À valider</b> pour le propriétaire : propositions groupées par domaine puis par fiche, avant → après, auteur, date, <b>Valider</b> / <b>Refuser</b> (avec motif), « Tout valider pour cette fiche », « Voir » en contexte, filtre « mes domaines », vue « Proposées par moi » pour le contributeur, décisions passées. Compteur dans le menu latéral et dans l\'en-tête.',
                'Valider applique la valeur et trace la décision dans l\'historique de la fiche ; refuser conserve la trace. Les objets métier et les termes gagnent un champ <b>Domaine métier</b>, qui détermine qui valide.',
                'Tant qu\'aucune personne n\'est déclarée, rien ne change : l\'application se comporte exactement comme avant.'] },
            { v: '9.6.0', d: '2026-09-08', t: 'Le code est découpé en sources lisibles ; le fichier livré est construit', items: [
                'Le code source vit désormais dans <b>studio-data/src/</b> : 55 fichiers découpés par <b>fonctionnalité</b> — noyau (état, moteur DuckDB, persistance, navigation, thème…), gouvernance (dictionnaire, listes de valeurs, objets métier, applications, glossaire, catalogue…), lineage, modèle de données, sources, qualité, séries temporelles, extraction, tableaux de bord. Chaque fichier a un rôle décrit dans <b>src/README.md</b>.',
                'Une commande, <code>node studio-data/build.mjs</code>, assemble ces sources en <b>un seul fichier</b> StudioDataV7.html, strictement équivalent (la première construction a été vérifiée octet par octet avec l\'ancien fichier). L\'application reste 100 % locale, un seul fichier à ouvrir.',
                '<code>node studio-data/build.mjs --check</code> vérifie que le fichier livré correspond bien aux sources ; la suite de tests l\'exécute. Règle : on modifie les sources, jamais le fichier construit.',
                'Aucun changement fonctionnel dans cette version.'] },
            { v: '9.5.1', d: '2026-09-07', t: 'Qualité & Audit : alertes sémantiques et inspecteur repliés par défaut', items: [
                'Sur l\'écran Qualité & Audit, les sections <b>Alertes sémantiques</b> et <b>Inspecteur d\'anomalies</b> sont désormais <b>repliées</b> à l\'ouverture : le tableau des colonnes arrive plus vite à l\'écran.',
                'Chaque titre replié porte un <b>compteur</b> (« 4 alerte(s) », « 12 anomalie(s) », ou « aucune » en vert) pour savoir ce qu\'il contient sans l\'ouvrir. Un clic déplie ; « Tout déplier / replier » reste disponible.'] },
            { v: '9.5.0', d: '2026-09-07', t: 'Catalogue navigable : fiche d\'attribut, retour, fil d\'Ariane', items: [
                'Chaque <b>attribut métier</b> a sa fiche dans le catalogue : cliquez un attribut dans la fiche de l\'objet pour l\'ouvrir — appartenance à l\'objet (cliquable pour remonter), nombre de valeurs, sensibilité, exemples, termes (modifiables), colonnes techniques qui l\'alimentent, applications et processus qui l\'utilisent, lineage dans la fiche, bouton « ✎ Modifier dans l\'objet ».',
                '<b>← Retour</b> et fil d\'Ariane en tête de chaque fiche ouverte depuis une autre (objet › attribut › colonne…) : on navigue et on remonte sans fermer le panneau.',
                'Des liens partout : depuis une colonne vers l\'attribut qu\'elle alimente, depuis un terme vers l\'attribut précis (et plus seulement l\'objet), depuis un attribut vers ses colonnes et ses applications.',
                'Les attributs sont trouvables par la recherche (nom, définition, provenance, objet) et par le type « Attribut métier » de la facette, sans encombrer la liste par défaut. Le type « Attribut » technique s\'appelle désormais « Colonne » pour lever l\'ambiguïté.'] },
            { v: '9.4.1', d: '2026-09-04', t: 'Menu latéral réduit : un vrai rail d\'icônes', items: [
                'Réduit, le menu latéral affichait des icônes décalées et rognées. Il devient un <b>rail de 64 px</b> : logo, phases et sous-écrans du groupe ouvert en icônes <b>centrées</b>, alignées, sans bordure ni retrait ; l\'écran actif reste surligné ; les libellés apparaissent au survol.',
                'Les boutons du pied (Sauvegarde, Importer, Exporter, Déployer) sont centrés de la même façon.'] },
            { v: '9.4.0', d: '2026-09-04', t: 'Gouvernance : une seule navigation', items: [
                'Trois menus se répétaient : le menu latéral, les familles dans l\'en-tête (Découvrir, Patrimoine, Acteurs, Sens métier…) et une rangée de puces dans le panneau. Le <b>menu latéral</b> devient l\'unique navigation.',
                'L\'en-tête n\'affiche plus les familles que lorsque le menu latéral est <b>réduit</b> (icônes seules) : elles prennent alors le relais, sinon elles disparaissent.',
                'Le panneau de gouvernance perd son titre redondant et sa rangée de puces ; il garde un fil d\'Ariane discret (« Sens métier › Objets métier »), le <b>Mode consultation</b> et <b>Import en masse</b>.',
                'Rien n\'est perdu : tous les écrans restent accessibles par le menu latéral ; en consultation, seuls les écrans autorisés y figurent, comme avant.'] },
            { v: '9.3.3', d: '2026-09-04', t: 'Créer un terme inconnu : un bouton explicite, plus seulement la touche Entrée', items: [
                'Dans le champ « ＋ Ajouter un terme… », dès que vous tapez, un bouton apparaît : <b>« ＋ Créer « votre texte » »</b> (vert) si le terme n\'existe pas encore, <b>« ↵ Relier »</b> (bleu) s\'il existe déjà. Un clic suffit ; la touche Entrée fonctionne aussi. Il n\'était pas évident qu\'il fallait valider par Entrée, et quitter le champ ne créait rien.',
                'Le champ est un peu plus large et son libellé n\'est plus tronqué.'] },
            { v: '9.3.2', d: '2026-09-04', t: 'Ajouter un terme depuis le catalogue, sur l\'objet, l\'attribut, l\'application', items: [
                'La fiche du catalogue devient un point d\'entrée pour poser un terme : sur un <b>objet métier</b> (« Termes de l\'objet ») et sur <b>chacun de ses attributs</b> (« Attributs et leurs termes »), sur une <b>application</b> ou un <b>processus</b>, et depuis une <b>colonne</b> sur l\'attribut qu\'elle alimente. La fiche se reconstruit aussitôt.',
                'Le champ d\'ajout s\'annonce clairement : « ＋ Ajouter un terme… ». Tapez un terme existant (suggestions) ou un nouveau, puis Entrée : il est créé dans le glossaire et relié sur place. Même composant dans le dictionnaire, la fiche de l\'objet, le formulaire d\'attribut, la fiche application et le glossaire par objet.'] },
            { v: '9.3.1', d: '2026-09-04', t: 'Catalogue : les termes des attributs ne sont plus affichés comme ceux de l\'objet', items: [
                'La carte et la fiche d\'un objet métier n\'affichent plus, en tags, les termes qui sont en réalité posés sur ses <b>attributs</b> — seuls les termes de l\'objet lui-même apparaissent.',
                'Ces termes d\'attributs restent <b>cherchables</b> (chercher « Revenu » trouve toujours l\'objet Client) et la fiche les liste à part, attribut par attribut : « 🔹 Chiffre d\'affaires → 📖 Revenu », chaque terme cliquable.'] },
            { v: '9.3.0', d: '2026-09-04', t: 'Les termes deviennent des tags, partout, avec ajout direct', items: [
                'Fini le mélange liste déroulante + pastilles : les termes d\'un <b>attribut</b>, d\'un <b>objet métier</b>, d\'une <b>application</b> ou d\'un <b>processus</b> s\'affichent en <b>tags</b>, tous au même niveau, chacun avec ✕ pour le retirer et un clic pour l\'ouvrir dans le glossaire.',
                'Champ <b>« + terme »</b> à côté des tags : tapez un terme existant (suggestions) ou un nouveau, puis Entrée — il est créé dans le glossaire et relié dans la foulée. Disponible dans le <b>dictionnaire par objet</b>, la <b>fiche de l\'objet</b> (carte d\'identité et formulaire d\'attribut) et la fiche <b>application / processus</b>.',
                'Le <b>glossaire</b> gagne deux vues : <b>Par objet & attribut</b> (chaque objet, ses termes, puis chaque attribut avec ses tags) et <b>Par application & processus</b> — la liste « Par terme » reste disponible. Un terme ouvert depuis un tag est mis en évidence.',
                'En vue technique du dictionnaire, les termes hérités de l\'attribut alimenté apparaissent en tags verts, non modifiables ici (ils se gèrent sur l\'attribut).'] },
            { v: '9.2.2', d: '2026-09-04', t: 'Le dictionnaire montre tous les termes d\'une donnée', items: [
                'Depuis la 9.2.0 un attribut peut porter plusieurs termes, mais le dictionnaire n\'en affichait qu\'un. La colonne « Terme » du <b>dictionnaire par objet</b> montre désormais le terme principal <b>et</b> tous les autres termes posés depuis le glossaire, en pastilles, avec retrait ✕ et un sélecteur « + autre terme… » pour en poser un de plus sans quitter le dictionnaire.',
                'En <b>vue technique</b> (colonnes), la colonne affiche en plus les termes hérités de l\'attribut d\'objet qu\'elle alimente, marqués comme hérités.',
                'Un attribut replié (colonnes numérotées) affiche l\'union des termes de ses membres.'] },
            { v: '9.2.1', d: '2026-09-04', t: 'Titre de l\'onglet aligné sur la version', items: [
                'L\'onglet du navigateur affichait « Studio Data V5 - Qualité & BI », un numéro figé depuis longtemps. Il affiche désormais <b>« Studio Data 9.2.1 »</b>, calculé depuis la version de l\'application : il restera juste à chaque mise à jour.'] },
            { v: '9.2.0', d: '2026-09-04', t: 'Le glossaire parle métier : un terme se pose sur un attribut, un objet, une application ou un processus', items: [
                'Fini le « Lier colonne » : un terme est un nom métier, il se pose sur ce qui a un sens pour le métier — un <b>attribut d\'objet</b> (sélecteur objet ▸ attribut), un <b>objet métier</b>, une <b>application</b> ou un <b>processus</b>. Une colonne de fichier n\'est qu\'une provenance : elle <b>hérite</b> du terme de l\'attribut qu\'elle alimente.',
                'Le lien est porté des deux côtés : lier un attribut depuis le glossaire remplit son champ « Terme », et choisir un terme dans le formulaire de l\'attribut le fait apparaître dans le glossaire. Un attribut peut porter plusieurs termes.',
                '<b>Migration automatique</b> : chaque ancien lien vers une colonne qui alimente un attribut devient un lien vers cet attribut. Les colonnes qui n\'alimentent encore aucun attribut restent visibles comme « ancien lien fichier », à reporter ou à retirer — rien n\'est perdu.',
                'Catalogue : les applications, processus et objets portent leurs termes (recherche par synonyme, pastilles dans la fiche) ; la fiche d\'un terme liste attributs, objets, applications et processus désignés, tous cliquables. Une colonne affiche les termes hérités de son attribut.',
                'La fiche d\'une application ou d\'un processus affiche ses termes ; supprimer un terme nettoie les attributs qui le portaient.'] },
            { v: '9.1.1', d: '2026-09-04', t: 'Correctif : « variantes de casse » fantômes à l\'audit', items: [
                '<b>Le symptôme</b> : l\'audit affichait par exemple 26 variantes de casse sur un attribut, et le détail répondait « aucune ligne en anomalie ».',
                '<b>La cause</b> : le compteur était la différence de deux <i>estimations</i> approchées (nombre de valeurs distinctes, et nombre de valeurs distinctes une fois en majuscules). Sur une colonne à forte cardinalité, le bruit de ces estimations fabriquait un écart qui n\'existait pas, alors que la consultation du détail, elle, est exacte.',
                '<b>La correction</b> : le nombre de variantes est recompté <b>exactement</b> (COUNT DISTINCT) sur toutes les colonnes, dans une passe dédiée par lots. Vérifié sur un vrai DuckDB : 200 000 identifiants sans variante → 0 (l\'ancien calcul donnait un écart de plusieurs milliers) ; Paris / PARIS + lyon / Lyon → 2, et le détail liste exactement les lignes concernées. Une colonne sans variante affiche 0 et n\'est plus cliquable.'] },
            { v: '9.1.0', d: '2026-09-04', t: 'Lineage métier : applications → objet → usages, sans les fichiers', items: [
                'Le graphe de lineage d\'un <b>objet métier</b> et celui d\'un <b>attribut</b> ne passent plus par les fichiers : on lit directement <b>quelle(s) application(s) produisent</b> l\'objet, l\'objet, et <b>qui l\'utilise</b> (applications, processus). La table de provenance reste rappelée en sous-titre du nœud application (« via CLIENTS »).',
                'Une table destinataire est remplacée par l\'application qui la lit (« diffusé vers »). Une source sans application rattachée reste affichée, signalée « sans application », pour ne rien cacher.',
                'Case <b>« 📄 Afficher les fichiers »</b> dans l\'en-tête de chaque graphe (fiche catalogue, fiche objet, formulaire d\'attribut) pour rétablir le détail table par table. Le choix est mémorisé.',
                'L\'onglet Lineage (vue systèmes, bout en bout) intégrait déjà les fichiers aux applications par défaut : les trois graphes racontent maintenant la même histoire.'] },
            { v: '9.0.0', d: '2026-09-04', t: 'La fiche d\'un objet métier, repensée pour voir, modifier et enrichir', items: [
                '<b>Carte d\'identité</b> : nom, statut, propriétaire, contributeurs et définition (sur deux lignes) en tête, et surtout un <b>score de complétude</b> (« fiche complète à 62 % ») avec la liste de ce qui manque — chaque manque est un bouton qui mène directement au champ ou au filtre concerné (définition, propriétaire, source maître, attributs non alimentés, sans définition, sans usage, validation).',
                '<b>Espace « Attributs & composition » en maître-détail</b> : à gauche la liste de tous les attributs (propres et par facette) avec leur provenance et trois voyants (alimenté, défini, utilisé) ; à droite un <b>vrai formulaire</b> pour l\'attribut sélectionné : identité, <b>sens métier</b> (définition, exemples avec échantillonnage depuis la source, sensibilité, terme du glossaire), provenance (colonnes techniques), usages (applications et processus à cocher, source spécifique), ordre, lineage, suppression.',
                'Ces champs de sens n\'étaient jusqu\'ici accessibles que dans le dictionnaire par objet : on enrichit désormais un attribut là où on le structure.',
                'Recherche et <b>filtres</b> (Tous / Non alimentés / Sans définition / Sans usage), navigation au clavier ↑ ↓ dans la liste, sélection automatique du nouvel attribut après « + Attribut ».',
                'Les <b>facettes</b> s\'ouvrent comme des fiches : nom, cardinalité, table, filtre fonctionnel, applicabilité, attributs ; « + Facette » propose un petit formulaire de création. Les objets référencés ont leur propre fiche.',
                'La <b>vue Tableau</b> historique reste disponible d\'un clic (▤ Fiche / ▦ Tableau) : rien n\'est perdu, y compris le glisser-déposer.',
                'Mode sombre et contrastes vérifiés sur l\'ensemble du nouvel espace.'] },
            { v: '8.7.0', d: '2026-09-04', t: 'Structure d\'un objet métier : un tableau d\'attributs enfin lisible', items: [
                '<b>La photo de l\'utilisateur montrait des noms rognés</b> (« ANNEE_ », « BASE_DI », « COMME ») : les deux sélecteurs « table ▸ colonne », affichés en permanence sur chaque ligne, écrasaient la colonne du nom. Le tableau passe en <b>largeurs fixes</b> — le nom métier dispose de 230 px garantis, quoi qu\'il y ait à côté.',
                '<b>Une ligne par attribut</b> : le sélecteur de colonne technique est masqué et n\'apparaît que sur « + colonne », pré-positionné sur la table maître de l\'objet. Il reste ouvert d\'office quand l\'attribut n\'est alimenté par rien, avec l\'alerte « ⚠ non alimenté ».',
                'Les pastilles « table.colonne » mettent la <b>colonne en évidence</b> et la table en retrait, avec l\'intitulé complet au survol ; les longues colonnes ne cassent plus la mise en page.',
                'Ordre : poignée ⠿ et boutons ⤒ ▲ ▼ ⤓ sur une seule ligne. Propriétaire : le champ indique « = <i>propriétaire de l\'objet</i> » au lieu de « hérite du » tronqué.',
                'Nb de valeurs : un seul sélecteur par ligne ; la mention « observé : n valeurs » n\'apparaît que si des colonnes numérotées ont été détectées sans déclaration. Mêmes règles pour les attributs des <b>facettes</b> (composants).',
                'La liste des objets ne vole plus la place : largeur fixe (230 px) à côté de la fiche sur grand écran, et <b>au-dessus de la fiche</b> en cartes alignées sous 1536 px — la fiche dispose alors de toute la largeur.',
                'Champs et textes relevés (12,5 px dans les cellules, intro en 11,5 px) — plus de 10 px gris clair. Contrastes vérifiés dans les deux thèmes.'] },
            { v: '8.6.0', d: '2026-09-04', t: 'Le catalogue parle métier — et le lineage d\'un objet s\'affiche comme celui d\'un attribut', items: [
                '<b>Vue métier par défaut</b> : le catalogue présente d\'abord les <b>objets métier, applications, processus</b>, termes, règles et rapports. Les tables, colonnes et vues issues des sources restent indexées (chercher « CA_HT » les trouve) mais n\'apparaissent plus par défaut.',
                'Bascule <b>🏛 Métier / ▦ Tout</b> dans la barre des résultats ; sous le compteur, « + n donnée(s) technique(s) masquée(s) » indique ce que la recherche trouverait en couche technique, en un clic. Cocher un type technique dans la facette (Table, Attribut…) l\'inclut aussi.',
                'Un état vide honnête : « Rien côté métier — mais n donnée(s) technique(s) correspondent » avec le bouton pour les afficher, au lieu d\'un « aucun actif » trompeur.',
                '<b>Lineage d\'un objet métier dans sa fiche</b> : « 🕸 Voir le lineage » ouvre désormais le graphe <b>dans la fiche</b>, comme pour un attribut — applications productrices → sources maître / contributrices → objet → applications, processus et tables destinataires, avec le nombre d\'attributs utilisés par consommateur. Un lien « ↗ Par attribut » conduit à la vue détaillée de l\'onglet Lineage.',
                'Le même graphe est disponible dans <b>Objets métier ▸ Applis & usages</b> via le bouton « 🕸 Lineage de l\'objet », dans l\'encart déjà utilisé pour le lineage d\'attribut.',
                'La fiche d\'un objet liste sa <b>chaîne</b> (applications productrices, sources techniques avec leur rôle, consommateurs), chaque entrée cliquable. Les liens vers une donnée technique masquée basculent automatiquement la couche « Tout » : un lien ne tombe jamais dans le vide.'] },
            { v: '8.5.0', d: '2026-07-31', t: 'Les termes du glossaire deviennent de vrais synonymes dans le catalogue', items: [
                '<b>Un terme est le nom métier d\'une donnée</b> — « Chiffre d\'affaires » pour la colonne <code>CA_HT</code>. Le modèle savait déjà relier un terme de trois façons (liens du glossaire vers des colonnes, rattachement à des objets métier, champ « Terme » posé sur un attribut ou une colonne), mais le catalogue n\'en restituait <b>aucune</b>.',
                '<b>Chercher le terme trouve maintenant la donnée</b> : les noms de termes entrent dans le texte de recherche des colonnes qu\'ils désignent, et réciproquement les données désignées rendent le terme trouvable. C\'est le comportement de synonyme attendu.',
                'La <b>fiche d\'un terme</b> liste tout ce qu\'il désigne — colonnes, objets métier, attributs — avec la provenance du lien, et chaque entrée est <b>cliquable</b> vers la fiche correspondante.',
                'La <b>fiche d\'une colonne</b> affiche ses termes en pastilles « 📖 synonymes métier » cliquables — et plus jamais l\'identifiant brut <code>gl_…</code> qui s\'affichait à la place du nom.',
                'La carte du terme dans le catalogue compte désormais <b>tout</b> ce qu\'il désigne (« désigne 4 donnée(s) »), pas seulement les liens directs du glossaire.'] },
            { v: '8.4.1', d: '2026-07-31', t: 'Correctif définitif des pavés bleu/brun de l\'assistant', items: [
                '<b>La photo de l\'utilisateur montrait le défaut encore présent dans la 8.4.0</b> : les deux cartes de l\'assistant en pavés pleins bleu et brun, texte illisible. Le correctif 8.3.0 était incomplet : le sélecteur réparé attrapait encore <code>bg-indigo-50/40</code>, car « bg-indigo-5 » est un préfixe de « bg-indigo-50 ».',
                'Les sélecteurs des boutons pleins passent en <b>correspondance exacte de jeton</b> (<code>[class~="bg-indigo-600"]</code>) : ils ne peuvent plus attraper une nuance voisine ni une variante hover.',
                '<b>Pourquoi les tests ne l\'avaient pas vu</b> : l\'audit de contraste n\'ouvrait jamais la fenêtre de l\'assistant, et injectait Tailwind AVANT les styles de l\'application alors qu\'en réel il s\'injecte APRÈS. L\'audit couvre désormais l\'assistant et la bulle du guide, reproduit la cascade réelle, et désactive les transitions pendant la mesure (elles faisaient photographier des couleurs interpolées à mi-course).',
                'Au passage : en-tête de la bulle du guide, « j\'attends votre action… », « Quitter le guide » et le bouton 🧭 Assistant relevés au seuil AA dans les deux thèmes.'] },
            { v: '8.4.0', d: '2026-07-31', t: 'Des graphes lisibles — disposition, éventails, mode sombre', items: [
                '<b>Les captures de l\'utilisateur montraient des cartes illisibles</b> : nœuds empilés dans un coin, éventail de vingt arêtes « consommé par » convergeant vers un point, vingt étiquettes superposées au même endroit, cartes qui se recouvraient, violet sombre invisible sur fond nuit.',
                '<b>Disposition refaite</b> (graphe « bout en bout », modèle objet, fiche catalogue) : ordre <b>barycentrique</b> dans chaque colonne — un nœud se place en face de la moyenne de ses voisins, ce qui démêle les croisements ; une colonne de plus de 12 nœuds est <b>repliée en sous-colonnes</b> au lieu d\'une pile infinie ; chaque colonne est <b>centrée verticalement</b>.',
                '<b>Éventails agrégés</b> : quand ≥ 3 arêtes portent le même libellé vers ou depuis le même nœud, une seule étiquette « consommé par × 10 » remplace la pile. Même règle pour les pastilles de la carte « Structure &amp; santé », qui glissent en plus le long de la courbe au lieu de s\'accrocher toutes au même point.',
                '<b>Plus aucun recouvrement de cartes</b> : la carte Lineage mesure désormais la hauteur RÉELLE de chaque carte (badges qui passent à la ligne, listes d\'attributs) et rejoue la disposition si l\'interligne ne suffit pas.',
                '<b>Arêtes courbes</b> entre colonnes (au lieu de segments qui traversaient les nœuds), étiquettes au <b>halo assorti au thème</b> (fini le halo blanc en pâté sur fond nuit), et masquées en zoom lointain où elles ne sont que du bruit.',
                '<b>Palette sombre dédiée aux flux</b> : violet clair pour les usages, teintes portées pour sain/à surveiller/alerte — le violet profond disparaissait dans le fond.',
                'Le tout sous tests : chevauchements comptés (0 exigé), agrégation d\'éventail, courbes, classes de thème, repli des colonnes hautes.'] },
            { v: '8.3.0', d: '2026-07-31', t: 'Passe de contraste complète — mesurée, dans les deux thèmes', items: [
                '<b>Un audit automatique</b> (ratio WCAG calculé sur chaque texte réellement rendu, 17 écrans × 2 thèmes) a compté <b>519 textes sous le seuil de lisibilité</b> — dont des boutons littéralement <b>blanc sur blanc</b> (« + Filtre », « Remplir par fichier », « Mode assistant »). Après la passe : <b>0</b>, hors trois faux positifs de mesure documentés.',
                '<b>La cause des boutons invisibles</b> : un sélecteur CSS attrapait « hover:bg-indigo-50 » en croyant reconnaître un bouton plein indigo, lui donnait un texte blanc, puis une autre règle remettait le fond blanc. Corrigé à la racine.',
                '<b>Le texte « discret » reste discret, mais lisible</b> : tous les gris trop clairs (libellés, provenances, aides, barre de contexte, fil d\'Ariane) sont relevés au seuil AA — 4,5:1 minimum. Le plus petit corps passe de 9 à 10 px : sous 10 px, rien n\'est lisible quel que soit le contraste.',
                '<b>Boutons pleins</b> : les fonds vert, ambre, ciel et rouge ne portaient pas le blanc (jusqu\'à 1,9:1 pour l\'ambre). Ils passent en teintes porteuses (vert 4,5+, ambre 6+, rouge 5+).',
                '<b>Mode sombre remis d\'aplomb</b> : l\'accent violet éclairci ne portait plus le blanc (2,7:1) — il redevient porteur ; les gris tamisés du sombre sont relevés ; les pastilles translucides posées sur un fond plein coloré deviennent opaques, sinon la teinte du parent traversait et noyait le texte.',
                'L\'audit devient une <b>suite de non-régression permanente</b> : tout futur écran qui repasserait sous le seuil fera échouer les tests.'] },
            { v: '8.2.0', d: '2026-07-31', t: 'L\'assistant devient un guide SUR l\'écran réel + consultation élargie', items: [
                '<b>L\'assistant en fenêtre est remplacé.</b> Il refaisait les écrans en plus simple dans une fenêtre à part : en sortant, on n\'avait toujours pas appris où sont les commandes. Le guide se déroule désormais <b>sur les écrans eux-mêmes</b> : il surligne l\'endroit précis où cliquer, explique quoi faire, et rend <b>tout le reste de l\'application non cliquable</b> (voile sombre autour de la zone active).',
                'Il <b>observe l\'état réel</b> et n\'avance que quand l\'action est accomplie : source chargée, écran ouvert, colonne ajoutée, règle créée, exécution faite. Les étapes facultatives ont un bouton « Étape suivante » ; toutes peuvent être passées, et « Quitter le guide » est toujours là — rien n\'est perdu.',
                'Deux parcours : <b>⚗️ Extraction</b> (charger une source si besoin, table de départ, colonnes, filtre facultatif, aperçu réel, génération) et <b>✅ Qualité</b> (créer une règle, la régler ligne par ligne, l\'exécuter sur les vraies données, lire le score). À la fin, l\'utilisateur a produit un vrai résultat <b>avec les vraies commandes</b>, qu\'il saura retrouver seul.',
                'Si la cible d\'une étape est introuvable, le guide le dit et propose de passer — jamais d\'écran figé.',
                '<b>Mode consultation élargi.</b> La coupe à deux écrans était trop stricte : restent consultables tous les écrans qui <b>présentent</b> le référentiel — Catalogue, Dictionnaire, Modèle de données, Objets métier, Applications &amp; processus, Glossaire, Listes de valeurs, Lineage, Historique. Seuls les trois postes d\'<b>administration</b> sont retirés : Périmètres, Sensibilité, Surveillance des sources.'] },
            { v: '8.1.1', d: '2026-07-31', t: 'Consultation : le menu se réduit aux écrans qui présentent le référentiel', items: [
                '<b>Masquer les commandes ne suffisait pas.</b> Les 13 écrans de la Gouvernance restaient au menu ; or, privés de leurs commandes, ceux qui servent à <b>administrer</b> — composer un objet, tenir le glossaire, classer la sensibilité, surveiller les sources — ne disaient plus grand-chose, et leur seule présence faisait chercher au lecteur des choses qu’il ne peut pas faire.',
                'En mode consultation, la Gouvernance ne propose plus que le <b>Catalogue</b> — la porte d’entrée, qui indexe tables, colonnes, objets métier, termes, applications et règles avec sa fiche de détail — et le <b>Dictionnaire</b>, qui donne le détail attribut par attribut, par objet métier ou par table.',
                'La réduction s’applique aux <b>trois endroits</b> où ces écrans apparaissent : le rail de gauche, les familles de la barre du haut, et les puces de l’écran.',
                'Aucune <b>impasse</b> : les raccourcis qui menaient à un écran retiré (« Ouvrir la fiche complète », « créer une liste ») disparaissent aussi, et ouvrir un écran retiré par un autre chemin ramène au Catalogue. Si le lecteur active le mode depuis un écran non consultable, il est déposé sur le Catalogue.',
                'Décocher la case rend l’intégralité du menu.'] },
            { v: '8.1.0', d: '2026-07-31', t: 'Mode consultation de la Gouvernance', items: [
                '<b>Beaucoup de gens ouvrent la gouvernance pour LIRE</b> : comprendre ce qui a été défini, relire des définitions, préparer un avis. Chaque champ de saisie les invitait pourtant à écrire, et une modification par mégarde ne se voyait pas.',
                'Une case <b>👁 Mode consultation</b> en haut de la Gouvernance masque <b>toutes les commandes de modification</b> de ses 13 écrans. Ce qui sert à lire reste intact : navigation entre écrans, recherche et facettes du catalogue, choix de l’objet ou de la table, onglets d’une fiche, audit d’objet, zoom et recentrage des graphes, aperçus, exports.',
                '<b>Ce n’est pas une sécurité, et le bandeau le dit</b> : la case se décoche, et l’application reste un fichier unique lisible. C’est un garde-fou contre la modification accidentelle, et un mode de démonstration.',
                'La règle est <b>« interdit par défaut »</b> : une commande n’est laissée active que si elle est explicitement marquée comme servant à lire. Oublier un marquage rend une commande de lecture invisible — visible et sans conséquence ; l’inverse laisserait un lecteur modifier le référentiel sans s’en apercevoir. La protection échoue du côté sûr.',
                '<b>Portée : la Gouvernance seulement.</b> Charger une source, extraire, analyser restent disponibles — ces écrans ne touchent pas au référentiel. La bascule vaut pour la session et ne modifie rien de ce qui est enregistré.'] },
            { v: '8.0.0', d: '2026-07-31', t: 'Mode assistant : extraire et contrôler, guidé pas à pas', items: [
                '<b>Les deux fonctions les plus utiles étaient les plus intimidantes.</b> L\'écran d\'extraction offre colonnes calculées, synthèses de tables liées, hiérarchies aplaties et agrégats ; celui des règles propose vingt types de contrôles. Un nouvel utilisateur ne savait pas par où commencer et abandonnait avant d\'avoir produit quoi que ce soit.',
                'Un bouton <b>🧭 Assistant</b> dans l\'en-tête ouvre deux parcours guidés, également accessibles depuis <b>⚗️ Extraire</b> et <b>📏 Règles &amp; score</b>. Sur un outil vide, l\'assistant se propose <b>de lui-même, une seule fois</b>.',
                '<b>Assistant Extraction</b> — quatre questions : la source, les colonnes à sortir, un filtre facultatif, puis une vérification qui affiche le <b>nombre de lignes en sortie et un aperçu réel</b> avant de lancer. Le récapitulatif est écrit en français : « extraire 6 colonnes de CLIENT.csv, en ne gardant que les lignes où VILLE = PARIS ».',
                '<b>Assistant Qualité</b> — l\'outil <b>mesure la source</b> (remplissage, unicité, nombre de valeurs distinctes, nature numérique) et <b>propose</b> des contrôles : colonne obligatoire, identifiant sans doublon, liste de valeurs observée, intervalle numérique. Chaque proposition affiche <b>la mesure qui la justifie</b> — « 12 340 valeurs, toutes différentes et toutes renseignées ». Vous cochez, ajustez la criticité, et l\'assistant crée les règles puis les exécute et affiche le score.',
                'La proposition est <b>prudente</b> : une colonne vide, trop peu remplie ou trop variée ne déclenche rien plutôt que de produire des faux positifs, et l\'intervalle numérique est proposé <b>décoché</b> — une plage observée n\'est pas une plage métier.',
                '<b>L\'assistant n\'a aucun moteur à lui</b> : il écrit dans les mêmes structures que les écrans complets, puis y emmène l\'utilisateur, configuration en place. Rien de ce qu\'il produit n\'est un cas particulier — tout reste modifiable, enregistrable et rejouable, et il enseigne où vivent les commandes au lieu de les remplacer.'] },
            { v: '7.14.0', d: '2026-07-31', t: 'Un attribut multivalué se DÉCLARE sur l\'objet métier', items: [
                '<b>La multiplicité ne pouvait être que subie.</b> Elle se déduisait de la structure technique — cardinalité du composant, colonnes numérotées — mais rien ne permettait de l\'<b>affirmer</b>. Or le métier sait souvent avant la source qu\'un client peut avoir plusieurs adresses de courriel, y compris quand <b>aucune source n\'est encore rattachée</b>.',
                'Chaque attribut porte désormais une multiplicité déclarée : <b>1 valeur</b>, <b>plusieurs sans limite</b>, ou <b>jusqu\'à n</b>. Elle se règle depuis le <b>dictionnaire par objet métier</b> et depuis la <b>fiche de l\'objet</b> (attributs du noyau comme attributs de composant), une nouvelle colonne « Nb de valeurs » dans les deux cas.',
                '<b>La déclaration l\'emporte sur la déduction</b> — c\'est le métier qui tranche — et le badge indique laquelle des deux s\'applique : une multiplicité seulement déduite est marquée « déduit », tant que personne ne l\'a confirmée.',
                'Sur un attribut replié (TEL_1, TEL_2…), la déclaration s\'applique à <b>toutes ses colonnes</b> d\'un coup.',
                'La multiplicité entre dans l\'<b>import en masse</b> : colonne « Nombre de valeurs » du gabarit, qui accepte <code>1</code>, <code>n</code>, <code>oui</code>, <code>non</code> ou un nombre. Une valeur illisible est <b>signalée ligne par ligne</b> au lieu d\'être enregistrée, et le gabarit exporte l\'existant pour l\'aller-retour.'] },
            { v: '7.13.0', d: '2026-07-31', t: 'Le multivalué au bon niveau : le groupe se répète, l\'attribut porte n valeurs', items: [
                '<b>La cardinalité était affichée attribut par attribut, ce qui était faux.</b> Quand un composant est en <code>1–N</code>, ce n\'est pas « la ville » qui est multivaluée : c\'est le <b>groupe d\'attributs</b> entier qui se répète. Répéter le badge sur chaque ligne laissait croire à une propriété de l\'attribut.',
                'Les attributs sont désormais <b>groupés par composant</b>, avec une ligne d\'en-tête qui porte la cardinalité, son sélecteur unique et la phrase qui l\'explique : <i>« un(e) Client peut avoir plusieurs Adresse ; ses 4 attributs vont ensemble — une occurrence, c\'est le bloc entier »</i>. Un groupe répétable est teinté d\'ambre, un groupe unique reste neutre.',
                '<b>Les colonnes numérotées deviennent un seul attribut métier.</b> <code>TEL_1, TEL_2, TEL_3</code> est un choix d\'implémentation ; le métier ne connaît qu\'un attribut <b>Téléphone</b> pouvant prendre <b>1 à 3 valeurs</b>. La colonne « Nombre de valeurs » l\'indique, et les colonnes d\'origine restent lisibles sous le nom.',
                'Ce qui est saisi sur un attribut replié — définition, exemples, sensibilité, terme — <b>s\'applique à toutes ses colonnes</b> : une seule saisie, aucune divergence possible entre <code>TEL_1</code> et <code>TEL_2</code>. Le renommer <b>renumérote</b> automatiquement chaque colonne.',
                'L\'échantillonnage d\'un attribut replié <b>balaie toutes ses colonnes</b> et dédoublonne, au lieu de n\'illustrer que la première.',
                'La bascule <b>Vue métier / Vue technique</b> rend à tout moment les colonnes une à une : le repliement est une lecture, il ne masque rien de force et ne modifie pas le modèle.',
                'Le repliement est <b>prudent</b> : il faut au moins deux colonnes de même base, un numéro de 1 à 99, et une base qui ne finit pas déjà par un chiffre — <code>CA_2024</code> ou <code>V1_2</code> ne sont pas repliés.'] },
            { v: '7.12.0', d: '2026-07-29', t: 'Le caractère multivalué d\'un attribut devient visible', items: [
                '<b>La vue ne disait pas si un attribut peut avoir plusieurs valeurs.</b> L\'information existait pourtant : elle est portée par la <b>cardinalité du composant</b>, mais n\'apparaissait que dans la fiche de l\'objet. On documentait donc « la ville de facturation » comme s\'il n\'y en avait qu\'une, alors que l\'objet peut en porter dix.',
                'Une colonne <b>Cardinalité</b> affiche pour chaque attribut <b>« 1 valeur »</b> ou <b>« plusieurs valeurs »</b>, ce dernier mis en évidence. Un attribut central vaut une fois par objet ; un attribut de composant suit la cardinalité de son composant — <code>1–N</code> et <code>N–N</code> sont multivalués, <code>1–1</code> et <code>N–1</code> ne le sont pas.',
                'L\'infobulle nomme le <b>composant d\'origine</b> et rappelle que le réglage lui appartient.',
                'La cardinalité du composant se règle <b>directement depuis la ligne</b>, sans passer par la fiche. Le sélecteur avertit explicitement qu\'il s\'applique à <b>tous</b> les attributs du composant, pas seulement à celui de la ligne.'] },
            { v: '7.11.0', d: '2026-07-29', t: 'Exemples échantillonnés depuis la source rattachée', items: [
                'Quand un attribut est rattaché à une colonne, un bouton <b>⟳</b> à côté du champ « Exemples » va chercher de <b>vraies valeurs</b> dans la donnée. Un bouton global fait la même chose pour tous les attributs de l\'objet d\'un coup.',
                '<b>Les valeurs retenues sont les plus fréquentes</b>, pas les premières venues : un exemple doit être représentatif. Les valeurs vides et les cellules ne contenant que des espaces sont écartées.',
                '<b>Une saisie manuelle n\'est jamais écrasée</b> par l\'échantillonnage global : dès qu\'un exemple est retouché à la main, il cesse d\'être considéré comme échantillonné et devient intouchable. Le compte rendu indique combien d\'attributs ont été complétés, combien ont été laissés intacts, combien n\'ont pas de colonne rattachée et combien n\'ont aucune valeur exploitable.',
                'Un attribut <b>sans colonne rattachée</b> le dit clairement au lieu d\'échouer, et une colonne <b>entièrement vide</b> est signalée plutôt que d\'inscrire un exemple vide.',
                'Les exemples issus de la source sont <b>reconnaissables d\'un coup d\'œil</b> (fond bleuté) et le message indique la colonne d\'où ils proviennent.',
                'Le balayage est <b>borné par un échantillon</b> : la commande reste instantanée même sur une source volumineuse.'] },
            { v: '7.10.0', d: '2026-07-29', t: 'Import en masse des attributs d\'objet métier', items: [
                'Nouvelle cible d\'import <b>« Attributs des objets métier »</b> : définition, exemples, sensibilité, terme de glossaire et propriétaire se chargent par fichier CSV ou Excel, pour tous les objets d\'un coup.',
                '<b>Le modèle est pré-rempli avec vos attributs existants</b> — objets centraux comme attributs de composants. On le télécharge, on complète les colonnes vides, on le réimporte : pas de saisie de la clé, pas de risque de faute de frappe sur les noms.',
                'Les colonnes du fichier sont <b>reconnues automatiquement</b> (Objet métier, Attribut, Définition, Exemples, Sensibilité, Terme, Propriétaire, Renommer en), et restent remappables à la main.',
                '<b>Les valeurs contrôlées le restent.</b> Une sensibilité hors liste est refusée avec l\'énumération des valeurs admises ; un terme absent du glossaire est refusé en invitant à le créer d\'abord. Rien n\'est enregistré à l\'aveugle.',
                '<b>Aucune création implicite</b> : un objet ou un attribut inconnu est signalé, jamais fabriqué à la volée — sans quoi une faute de frappe créerait un doublon silencieux. Le renommage d\'un attribut existe, mais uniquement via la colonne dédiée « Renommer en ».',
                'Un bouton <b>« Remplir par fichier »</b> ouvre directement cette cible depuis la vue Dictionnaire par objet métier.'] },
            { v: '7.9.0', d: '2026-07-29', t: 'Le sens appartient à l\'objet métier, plus à la colonne source', items: [
                '<b>Définition, exemples, sensibilité et terme du glossaire s\'enregistrent désormais sur l\'attribut de l\'objet métier</b>, et non plus sur la colonne mappée. On documente le concept, pas un détail technique — et un même concept alimenté par deux colonnes ne se saisit plus deux fois.',
                '<b>Le nom de l\'attribut devient modifiable dans cette vue.</b> Il n\'y était affiché qu\'en texte figé : impossible de corriger un libellé sans passer par la fiche de l\'objet.',
                '<b>Un attribut sans colonne rattachée se documente maintenant aussi.</b> Auparavant la ligne entière était grisée avec « mappez cet attribut pour le documenter » — on ne pouvait donc pas décrire un concept avant de savoir d\'où il viendrait.',
                '<b>La colonne technique passe au second plan</b> : elle n\'occupe plus une colonne du tableau mais s\'affiche en petit sous le nom de l\'attribut, comme une simple provenance. Les attributs des sources cessent ainsi d\'occuper le premier plan.',
                '<b>Rien de ce qui a été saisi n\'est perdu.</b> À l\'ouverture, ce qui existait sur les colonnes remonte une fois sur les attributs correspondants — sans jamais écraser une valeur déjà présente sur l\'attribut.',
                '<b>Le dictionnaire technique hérite.</b> Une colonne sans définition propre affiche celle de l\'objet métier en filigrane, avec la mention de l\'objet et de l\'attribut d\'origine. Une valeur saisie directement sur la colonne reste prioritaire.'] },
            { v: '7.8.0', d: '2026-07-29', t: 'Robustesse d\'ingestion : encodages, lectures fausses refusées, feuille Excel', items: [
                '<b>L\'encodage est maintenant tranché sur les octets AVANT la lecture</b> — marque d\'ordre, présence d\'octets nuls, puis validation UTF-8 stricte — au lieu d\'être deviné par essais après un échec. Un fichier Windows/ANSI ou UTF-16 est reconnu du premier coup, et l\'application dit lequel elle a détecté et pourquoi.',
                '<b>Deux corruptions silencieuses corrigées</b>, mesurées sur le moteur réel : un fichier <b>UTF-16 relu en Latin-1 ne provoquait aucune erreur</b> — on obtenait une unique colonne nommée « ÿþI » et des octets nuls partout, source marquée prête ; et la réparation « ignorer les lignes fautives » appliquée à un fichier ANSI <b>ne conservait aucune ligne</b> — une table vide, marquée prête elle aussi.',
                '<b>Une réparation n\'est plus acceptée sans contrôle.</b> Un résultat vide, portant des octets nuls, des caractères de remplacement, une marque d\'ordre en guise de nom de colonne ou des accents dégradés (« RÃ©paration ») est refusé, et l\'essai suivant est tenté. Quand une réparation écarte des lignes, le nombre conservé est annoncé.',
                '<b>Excel : la bonne feuille est choisie.</b> Seule la première feuille du classeur était lue, en silence — d\'où des sources vides quand le classeur commence par une page de garde. La feuille la plus fournie est désormais retenue, et un message nomme celle qui a été prise, celles qui ont été ignorées, et comment en charger une autre.',
                'Le principe commun à ces correctifs : <b>ce qui est décidé à la place de l\'utilisateur doit lui être dit</b>, et une lecture douteuse vaut mieux refusée que livrée.'] },
            { v: '7.7.0', d: '2026-07-29', t: 'Retrait du connecteur Google Sheets', items: [
                'Le connecteur Google Sheets introduit en 7.6 est <b>retiré</b> : il ne fonctionnait pas de façon fiable. Google ne sert le CSV qu\'aux feuilles publiées sur le web, et l\'autre voie de lecture dépend du navigateur et du poste — un partage « toute personne disposant du lien » ne suffit pas, contrairement à ce que la fonction laissait croire.',
                'Le retrait est complet : bouton, fenêtre de saisie, lecture, rechargement, pastille de source et type <code>gsheet</code>. Aucun résidu, aucune source existante affectée.',
                '<b>Pour charger une feuille Google, la voie sûre reste :</b> dans Google Sheets, <b>Fichier → Télécharger → Valeurs séparées par des virgules (.csv)</b>, puis charger le fichier avec le bouton <b>Fichiers</b>. Le résultat est identique, sans dépendre d\'un service extérieur.',
                'Studio Data redevient ainsi <b>intégralement local</b> : plus aucune fonction ne sort du poste de travail.'] },
            { v: '7.5.1', d: '2026-07-29', t: 'Horodatages lisibles dans le détail des échecs + la zone « séries visées » expliquée', items: [
                '<b>Les horodatages et les durées deviennent lisibles.</b> Le détail d\'un échec affichait « 2026-01-03 11:00:00 » et « 133200 » — exact, mais illisible. On lit désormais <b>03/01/2026 à 11h00</b> et <b>1 j 13 h</b>. La mise en forme est faite dans la requête, donc l\'export CSV en profite aussi, sans retraitement.',
                'Les colonnes sont renommées en conséquence : « Écart observé (s) » devient <b>Durée du trou</b>, « Pas attendu (s) » devient <b>Pas attendu de la série</b>, et une colonne <b>Ampleur</b> dit « 37 fois le pas » plutôt que de laisser faire le calcul.',
                '<b>La zone « CPT% » est expliquée.</b> Elle n\'était identifiée que par un exemple, sans dire à quoi elle sert. Elle s\'intitule maintenant <b>Limiter à certaines séries</b>, indique que le contrôle porte par défaut sur toutes les séries, explique à quoi sert la restriction (un fichier qui mélange un compteur cumulatif et une mesure instantanée : la monotonie ne vaut que pour le premier) et donne trois exemples commentés du caractère <b>%</b>.',
                'Le récapitulatif de chaque règle de série précise désormais explicitement « porte sur toutes les séries du fichier » quand aucune restriction n\'est posée.'] },
            { v: '7.5.0', d: '2026-07-29', t: 'Séries temporelles dans Données & Modèle + le détail des échecs explique la mesure', items: [
                '<b>La déclaration des séries passe de Gouvernance à Données &amp; Modèle.</b> C\'est une propriété de la <b>structure</b> de la donnée — au même titre qu\'une clé ou une relation — pas un acte de gouvernance. Nouvel écran dans la phase ①, à côté du Modèle de données.',
                '<b>Chaque règle explique ce qu\'elle mesure.</b> Un dépliant « Comment ce contrôle mesure l\'erreur » sous les réglages de chaque règle : ce qui est vérifié, la méthode employée, les seuils effectifs et l\'unité comptée. Les 20 types de règles sont documentés, pas seulement les nouveaux.',
                '<b>Le détail d\'un échec restitue le raisonnement, pas la ligne brute.</b> Pour un trou, la ligne fautive n\'existe pas : il n\'y a rien à montrer d\'une table. L\'inspection affiche donc le dernier point avant le trou, le point suivant, l\'écart observé, le pas attendu, le nombre de points manquants et la règle appliquée.',
                'Même principe pour les sept autres contrôles : le <b>saut</b> donne valeur précédente, valeur, écart absolu, variation en pourcentage et temps écoulé ; la <b>valeur figée</b> donne la valeur bloquée, le nombre de points, le début, la fin et la durée ; le <b>doublon</b> liste les valeurs concurrentes ; la <b>couverture</b> détaille points attendus, points manquants et taux ; la <b>fraîcheur</b> donne le dernier point, la référence et le retard.',
                'L\'<b>aberrant saisonnier</b> va plus loin : il indique la médiane du créneau, l\'écart à cette médiane, le seuil déclenchant, le nombre de points du créneau <b>et la dispersion effectivement utilisée</b> — écart médian, écart moyen si la série est trop stable, ou dispersion de la série entière. C\'est ce qui permet de juger si le seuil est bien réglé plutôt que de le subir.',
                'L\'explication de la règle est rappelée en tête du panneau d\'inspection, à côté du nombre d\'échecs.'] },
            { v: '7.4.0', d: '2026-07-29', t: 'Séries temporelles : maille, profil par série, calendrier de couverture et 8 contrôles', items: [
                'Toute l\'application reposait sur « une ligne = une entité ». Sur une série temporelle, une ligne est une <b>observation</b> et l\'entité est la <b>série</b> — d\'où deux angles morts : <b>la ligne qui n\'existe pas</b> (le trou), qu\'aucun contrôle par ligne ne peut voir, et la valeur impossible en tant que <b>variation</b> alors qu\'elle est banale dans la distribution globale.',
                '<b>Déclaration de la maille</b> (Données & Modèle → Séries temporelles) : clé de série (mono ou composite), horodatage, mesure, et pas déclaré ou détecté. Le pas est reconnu tout seul, y compris au format d\'horodatage français.',
                '<b>La régularité est mesurée, pas supposée.</b> Pour chaque série on calcule la part des intervalles égaux à l\'intervalle dominant : les séries cadencées sont jugées sur les trous et la couverture, les séries événementielles en sont exclues — elles ne sont pas fautives, elles sont d\'une autre nature.',
                '<b>Profil par série</b> : points, période couverte, pas, régularité, trous, plus long trou, couverture, doublons, plus long plateau, retard, min/max de la mesure.',
                '<b>Calendrier de couverture</b> : les séries en lignes, le temps en colonnes, une case par période — complet, partiel, aucun point, doublons. C\'est là qu\'on voit d\'un coup d\'œil qu\'un capteur s\'est arrêté.',
                '<b>Huit contrôles</b> à la maille série, dans Règles &amp; score : trou, doublon sur (série, horodatage), valeur figée, saut, monotonie, fraîcheur, aberrant saisonnier et couverture. Chacun compte l\'unité qui lui convient (intervalle, point, horodatage ou série).',
                'L\'<b>aberrant saisonnier</b> compare un point à la médiane du <b>même créneau</b> (heure du jour, jour de semaine ou mois) pour la <b>même série</b> : un creux nocturne normal cesse d\'être signalé, une valeur de jour en pleine nuit l\'est.',
                'Un <b>filtre de séries</b> permet de restreindre un contrôle à une partie des identifiants : sur un fichier mêlant un compteur cumulatif et une mesure instantanée, la monotonie ne vaut que pour le premier.'] },
            { v: '7.3.0', d: '2026-07-29', t: 'Correctif de chargement : la colonne « json » et les fichiers ignorés en silence', items: [
                '<b>La colonne « json ».</b> Quand la liste des colonnes n\'était pas transmise à l\'ingestion, chaque ligne se sérialisait en « {} » ; DuckDB, n\'ayant aucun objet à décrire, créait <b>une unique colonne nommée « json »</b> et la table paraissait chargée tout en étant inexploitable. Le défaut existait déjà en V6 — il ne vient pas de la refonte graphique.',
                'Correction en profondeur : les colonnes sont désormais <b>déduites des lignes</b> si l\'appelant ne les fournit pas, et surtout le schéma est <b>imposé à DuckDB</b> au lieu d\'être deviné — les noms de colonnes sont exactement ceux calculés, y compris avec accents, apostrophes, guillemets ou espaces. Si aucune colonne ne peut être établie, un message explicite le dit au lieu de livrer une table fantôme.',
                '<b>Import API.</b> Les lignes conservaient les noms de champs bruts alors que les en-têtes étaient nettoyés (BOM, espaces de bord) : toutes les valeurs ressortaient vides. Les deux côtés utilisent maintenant le même nom.',
                '<b>Fichiers ignorés en silence.</b> Déposer un format non pris en charge ne produisait aucun message — le fichier disparaissait sans explication. Un message nomme désormais le fichier, son format et la liste des formats acceptés.',
                '<b>Les fichiers .json sont acceptés</b> comme source, au même titre que CSV et Excel. Le tableau de lignes est retrouvé à la racine, sous un chemin explicite, ou automatiquement dans le document ; les valeurs imbriquées sont conservées en texte.'] },
            { v: '7.2.0', d: '2026-07-29', t: 'Épuration — pictogrammes partout, une couleur par intention', items: [
                'La 7.1 n\'avait converti que les titres : <b>999 émojis</b> restaient affichés, sur 127 caractères différents. Le jeu passe à <b>77 pictogrammes</b> et la conversion s\'applique désormais à toute l\'interface — libellés, boutons, puces, messages, états vides — et plus seulement aux titres.',
                'La garantie sur vos données est inchangée et reste testée : les <b>cellules de tableau</b>, les champs de saisie, les listes déroulantes et les canevas de graphes ne sont jamais réécrits. Un émoji non couvert reste affiché tel quel.',
                '<b>Fin de l\'arc-en-ciel</b> : 550 textes tiraient en rouge, vert, ambre et indigo saturés, chaque écran partant dans quatre directions. Le sens est conservé — une alerte reste rouge, une réussite verte — mais sur une seule nuance par intention, désaturée d\'un cran et accordée au thème clair comme au sombre.',
                '<b>Les dégradés disparaissent</b> au profit de surfaces franches.',
                'Les pictogrammes prennent le ton de leur contexte : discrets dans le corps de texte, plus affirmés dans les titres et les boutons.'] },
            { v: '7.1.0', d: '2026-07-29', t: 'Refonte totale du langage visuel — typographie, air, tracés', items: [
                'Le diagnostic, mesuré sur le fichier : 1012 graisses lourdes contre 24 moyennes, 270 libellés en capitales, 559 textes minuscules pour 74 grands, 1304 espacements serrés contre 437 généreux, 1891 bordures. C\'est cela qui donnait l\'aspect « outil d\'administration ».',
                '<b>Typographie</b> — police système (SF Pro sur Mac, Segoe UI sur Windows), échelle complète de 10,5 à 31 px, interlettrage négatif sur les titres. Le mur de gras tombe à deux niveaux : la hiérarchie se lit désormais à la taille et à la couleur, plus à la graisse.',
                '<b>De l\'air</b> — tous les espacements serrés sont dilatés d\'environ 40 %. Les champs et les boutons gagnent une hauteur confortable.',
                '<b>Les traits disparaissent</b> — les 1891 bordures deviennent des filets d\'un demi-ton. On ne cerne plus les blocs, on les pose : la séparation passe par l\'espace et une ombre très basse. Rayons unifiés en une seule famille de courbes.',
                '<b>Les émojis deviennent des tracés</b> — une table de 25 icônes vectorielles d\'un poids unique remplace les émojis de la navigation, des phases et des familles. Elles héritent de la couleur du texte ; tout émoji non couvert reste affiché tel quel.',
                '<b>Commandes</b> — trois registres de bouton seulement (plein, teinté, nu), pression tactile à l\'appui, anneau de focus à l\'accent. Champs au fond légèrement creusé, sans cadre dur.',
                '<b>Tableaux</b> — le quadrillage disparaît au profit d\'un filet par ligne, d\'une tête discrète en petites capitales et de cellules aérées.',
                '<b>Coque</b> — barre supérieure translucide et floutée, titre à l\'échelle d\'un vrai en-tête, sélection du rail en pastille pleine.',
                'Aucun écran n\'a été réécrit : la refonte porte sur le vocabulaire visuel dont ils héritent tous. Les fonctions, les calculs et le SQL sont inchangés.'] },
            { v: '7.0.0', d: '2026-07-29', t: 'Studio Data V7 — refonte de l\'interface : rail latéral, mode sombre, séparation nette', items: [
                'Navigation déplacée à GAUCHE dans un rail sombre : les phases deviennent des groupes dépliables, les écrans des entrées. Le rail se réduit à une bande d\'icônes, et cet état est mémorisé.',
                'La barre du haut est allégée : elle ne porte plus que le titre de l\'écran courant, son contexte, les familles de la gouvernance et le sélecteur de thème.',
                'Mode sombre complet — clair, sombre, ou automatique selon le système. Le choix est mémorisé et appliqué avant l\'affichage pour éviter tout clignotement.',
                'Séparation plus franche des parties : chaque écran est une surface posée sur le fond, avec sa propre bordure et son ombre ; le rail reste l\'ancrage visuel constant.',
                'Traitement graphique plus sobre : marque typographique à la place de la pastille dégradée, filet arc-en-ciel supprimé, palette resserrée, coins et ombres homogènes.',
                'Aucune fonctionnalité modifiée : les écrans n\'ont pas été réécrits, ils héritent du nouveau système visuel. La V6 reste disponible à l\'identique.'] },
            { v: '6.27.1', d: '2026-07-27', t: 'Listes de valeurs : le rattachement se fait depuis les trois écrans concernés', items: [
                'Le rattachement n\'apparaissait que dans le Dictionnaire en mode « par table technique ». Il est maintenant proposé aussi en mode « par objet métier », sur chaque attribut mappé à une colonne.',
                'Surtout : il se fait directement depuis la <b>fiche d\'une colonne dans Qualité &amp; Audit</b>, c\'est-à-dire là où la fausse alerte apparaît. Un bandeau explique la démarche et le rattachement est pris en compte immédiatement, sans relancer l\'audit.',
                'L\'écran des listes de valeurs gagne un sélecteur table + colonne pour rattacher depuis la liste elle-même, et une croix pour détacher un attribut déjà rattaché.',
                'Le même composant sert partout : le rattachement est identique et l\'attribut rattaché est mis en évidence en indigo.'] },
            { v: '6.27.0', d: '2026-07-27', t: 'Listes de valeurs : déclarer ce qu\'un attribut a le droit de contenir', items: [
                'Nouvel écran <b>Gouvernance ▸ 🎚️ Listes de valeurs</b>. Une liste se définit de deux façons : en clair, une ligne par valeur au format « code ; libellé ; statut » ; ou depuis une table déjà chargée servant de référentiel — vous désignez les colonnes code, libellé, statut, et une colonne « nom de liste » si la même table en porte plusieurs.',
                'Un champ « statut actif » permet de n\'accepter que les codes en vigueur : les codes obsolètes du référentiel cessent alors d\'être valides.',
                'Le <b>Dictionnaire</b> gagne une colonne « Liste de valeurs » pour rattacher un attribut à un référentiel, et un aperçu affiche à la demande les codes réellement retenus.',
                'Effet sur l\'audit : un attribut rattaché n\'est plus jugé sur la RARETÉ de ses valeurs. Des codes 1, 2, 3, 4 dont le 1 et le 2 sont rares ne déclenchent plus ni valeur aberrante, ni écart de format — c\'est normal. Le seul contrôle devient l\'APPARTENANCE : les valeurs hors référentiel sont signalées, inspectables et exportables.',
                'Nouveau type de règle de qualité « Appartenance à une liste de valeurs », qui réutilise le même référentiel et entre dans le score comme les autres.'] },
            { v: '6.26.0', d: '2026-07-27', t: 'Vues graphiques : étiquettes de liens discrètes et vrai plein écran', items: [
                'Les étiquettes des liens se chevauchaient dès qu\'un modèle comptait une dizaine de tables, au point de masquer le schéma. Elles n\'apparaissent plus qu\'au SURVOL de la case concernée, mise en évidence au passage — et le chemin emprunté reste de toute façon écrit sur la case elle-même.',
                'Une case à cocher « étiquettes des liens » permet de toutes les réafficher en permanence quand c\'est utile.',
                'Le plein écran englobe désormais la barre d\'outils : recherche, « colonnes choisies seulement », masquage des tables sans résultat pour l\'extraction ; vue métier/technique, focus objet métier et seuil pour le lineage. Elle reste collée en haut de l\'écran.',
                'Le graphe occupe exactement la hauteur restante sous cette barre, et les blocs secondaires (tuiles d\'indicateurs, légende) s\'effacent en plein écran pour laisser la place au schéma.'] },
            { v: '6.25.0', d: '2026-07-27', t: 'Profilage : fin de deux fausses alertes (dates factices, valeurs rares)', items: [
                'Le type « date » n\'est plus décidé sur la seule RESSEMBLANCE de forme. Une référence du genre 1234-56-78 ou un code aaaa-bb-cc en avait tous les traits sans être une date : l\'application exige désormais que 80 % des valeurs s\'ANALYSENT réellement comme des dates. Sinon la colonne redevient du texte et plus aucune alerte de date ne la concerne — la fiche explique pourquoi, avec le pourcentage réellement analysable.',
                'Une date dans le futur n\'est plus signalée comme une anomalie : une échéance, une fin de contrat ou une date planifiée sont normalement à venir. Seul l\'invraisemblable est remonté — au-delà d\'un siècle dans le futur, ce qui attrape les erreurs de saisie du type 2999. Le décompte des dates futures reste affiché à titre indicatif dans la fiche.',
                'L\'alerte « format hors motif dominant » ne s\'applique plus aux colonnes à faible cardinalité (15 valeurs distinctes ou moins). Sur un drapeau TRUE/FALSE ou une liste de statuts, la « forme » n\'a aucun sens : une valeur simplement RARE était signalée comme un écart de format, alors qu\'elle est parfaitement légitime.',
                'L\'export d\'audit distingue désormais les dates futures des dates invraisemblables.'] },
            { v: '6.24.0', d: '2026-07-27', t: 'Profilage : temps d\'audit divisé par près de 6', items: [
                'Sur une table de 120 000 lignes × 30 colonnes, l\'audit complet passe de 41 s à 7 s — soit moins que la version d\'avant l\'enrichissement du profilage (7,9 s), alors qu\'il calcule désormais bien davantage.',
                'Cause principale : les mesures de dates étaient évaluées sur TOUTES les colonnes, y compris de texte pur. Comme reconnaître une date suppose d\'essayer cinq formats, et que la mesure apparaissait quatre fois par colonne, cela représentait vingt tentatives d\'analyse par colonne et par ligne. Ces mesures sont maintenant réservées aux colonnes réellement reconnues comme dates.',
                'Même principe pour les statistiques numériques (moyenne, écart-type, quartiles) : elles ne sont plus calculées que sur les colonnes numériques.',
                'Le texte nettoyé de chaque colonne est calculé une seule fois par ligne puis réutilisé par tous les indicateurs, au lieu d\'être recalculé par chacun d\'eux.',
                'Aucun changement de résultat : les mêmes tests de profilage, aberrantes contextuelles, score robuste, formes de colonnes et colonnes redondantes passent à l\'identique.'] },
            { v: '6.23.0', d: '2026-07-27', t: 'Aberrantes contextuelles, score robuste MAD, et plein écran des graphes', items: [
                'Nouveau réglage « Comparer les valeurs à l\'intérieur de » dans l\'audit : en choisissant une colonne de regroupement (pays, catégorie, agence…), chaque valeur est comparée aux autres valeurs de SON groupe et non à toute la colonne. Un montant banal à Paris et énorme pour une commune rurale devient enfin détectable.',
                'Les groupes de moins de 5 lignes sont ignorés : sur si peu de valeurs, des quartiles ne veulent rien dire et ne produiraient que du bruit.',
                'Nouveau détecteur par score robuste (écart absolu médian). Contrairement à l\'écart-type, il ne se laisse pas gonfler par les valeurs qu\'il doit dénoncer ; contrairement à l\'écart interquartile, il rend une NOTE par ligne. La liste d\'anomalies est donc triée du plus grave au moins grave, avec la colonne SCORE_ECART — une file de traitement plutôt qu\'un tas indifférencié.',
                'Les deux nouveaux détecteurs sont inspectables (👁 Voir / ⬇ CSV) et présents dans l\'export d\'audit, comme les précédents.',
                'Plein écran : bouton ⛶ sur la vue graphique de l\'extraction et sur le graphe de lineage. Le graphe occupe toute la fenêtre et se redessine à la taille disponible ; on en sort par le bouton ou par la touche Échap.'] },
            { v: '6.22.0', d: '2026-07-27', t: 'Filtres : trouver une colonne dans un modèle large, isoler un objet métier dans le lineage', items: [
                'Extraction, vue graphique : une barre de filtre au-dessus du schéma. Recherche par nom de colonne OU de table (insensible à la casse et aux accents), option « colonnes choisies seulement », option « masquer les tables sans résultat ».',
                'Le filtre ne touche QUE l\'affichage : la configuration en cours n\'est jamais modifiée, et une colonne déjà cochée reste toujours visible pour ne pas perdre de vue ce qui est construit.',
                'Quand une table est conservée par le filtre, ses tables parentes le sont aussi : le chemin de jointure reste lisible de bout en bout. Un bandeau rappelle combien de tables et de colonnes sont affichées, et chaque case indique combien de colonnes sont masquées.',
                'Lineage : nouveau sélecteur « 🏛️ Objet métier » pour n\'afficher qu\'un référentiel et son voisinage — qui l\'alimente, qui le consomme. Le rayon de voisinage est réglable de 1 à 3 crans (2 par défaut, ce qui remonte jusqu\'aux sources des applications productrices).',
                'Si l\'objet choisi n\'apparaît pas sur la carte, le graphe le dit explicitement au lieu de s\'afficher vide.'] },
            { v: '6.21.0', d: '2026-07-27', t: 'Profilage : distribution, dates, forme des colonnes et colonnes redondantes', items: [
                'Distribution des colonnes numériques : P05, premier quartile, MÉDIANE, troisième quartile et P95. Un avertissement signale les colonnes où moyenne et médiane s\'écartent nettement — c\'est le signe d\'une série tirée par ses extrêmes, où la moyenne trompe.',
                'Valeurs atypiques au sens de l\'écart interquartile (Tukey), en plus de la règle des 3 écarts-types. Cette dernière suppose une distribution symétrique et ne détecte presque rien sur des montants ou des durées ; l\'écart interquartile ne fait aucune hypothèse de forme.',
                'Profil des colonnes de date : première et dernière date réellement présentes, nombre de dates dans le futur et de dates antérieures à 1900.',
                'Forme de chaque colonne, signalée par une pastille : clé candidate (toujours remplie et sans doublon), colonne constante (une seule valeur, donc sans information), faible cardinalité (bonne candidate pour une liste de valeurs autorisées).',
                'Colonnes redondantes : détection des colonnes strictement identiques ligne à ligne. Seules les paires plausibles sont comparées (même type, même cardinalité, même remplissage) et leur nombre est plafonné pour rester rapide sur les tables larges.',
                'Toutes les nouvelles anomalies (atypiques, dates futures, dates trop anciennes) sont inspectables avec « 👁 Voir » et exportables en CSV, comme les précédentes. L\'export d\'audit reprend l\'ensemble des nouvelles mesures.'] },
            { v: '6.20.0', d: '2026-07-27', t: 'Qualité : exécution d\'une règle à la fois + deux types de règles avancées', items: [
                'Chaque règle a désormais son bouton ▶ : elle s\'exécute seule, sans relancer toute la suite, et son résultat s\'affiche immédiatement (conforme, ou nombre de lignes/groupes en échec).',
                'Nouveau type « Condition SQL libre » : vous écrivez la condition que doit respecter une ligne valide, la règle liste celles qui ne la respectent pas. Lecture seule et une seule condition — les instructions d\'écriture et le « ; » sont refusés, avec un message explicite sous le champ.',
                'Nouveau type « Agrégat par groupe » : « pour chaque CONTRAT, le nombre de lignes où STATUT = ACTIF doit être ≤ 1 », « pour chaque COMMANDE, la somme des MONTANT doit être = 0 »… Regroupement sur une ou plusieurs colonnes, six agrégats, six opérateurs, et un filtre facultatif sur les lignes prises en compte.',
                'Pour ces règles d\'agrégat, l\'unité contrôlée est le GROUPE : le résultat compte les groupes non conformes, et l\'inspection « 👁 Voir / ⬇ CSV » affiche les lignes de ces groupes — donc directement ce qu\'il faut corriger.',
                'Les deux nouveaux types s\'utilisent aussi sur un objet métier (évalués sur sa table maître), entrent dans le score pondéré, les dettes qualité et les instantanés, comme toutes les autres règles.'] },
            { v: '6.19.0', d: '2026-07-27', t: 'Comparateur : clé composite et comparaison des seuls écarts de clé', items: [
                'La clé d\'identification n\'est plus limitée à UNE colonne. On empile autant de couples de colonnes (A ↔ B) que nécessaire : elles sont appariées dans l\'ordre et forment une clé composite.',
                'En SQL, les parties de la clé sont normalisées puis concaténées avec un séparateur impossible à trouver dans une donnée. Si une seule partie est vide, la clé entière est nulle et la ligne est écartée — même règle que pour une clé simple.',
                'Le rapport restitue une colonne de sortie PAR partie de clé (CLE_<colonne>), plus lisible qu\'une clé collée en un seul champ.',
                'Nouveau mode : si aucune correspondance de valeurs n\'est renseignée, la comparaison porte uniquement sur les ÉCARTS DE CLÉ — les clés présentes d\'un côté et pas de l\'autre. Le message « Mappez au moins une colonne » disparaît.',
                'Le résumé s\'adapte : clés évaluées, présentes des deux côtés, en plus dans A (absentes de B), en plus dans B (absentes de A). En mode classique, la tuile « Lignes absentes » précise désormais la répartition entre les deux sens.',
                'Confort : choisir une colonne de clé côté A propose automatiquement celle de même nom côté B.'] },
            { v: '6.18.0', d: '2026-07-27', t: 'Tables conçues : vue graphique optionnelle — relier les sources en tirant des traits', items: [
                'Nouvelle case à cocher « 🔗 Vue graphique » dans le concepteur de table. Elle AJOUTE un schéma au-dessus du formulaire habituel, qui reste disponible et synchronisé : rien n\'est remplacé.',
                'À gauche les sources contributrices avec leurs colonnes, à droite la table conçue avec ses attributs. Les alimentations existantes sont dessinées en traits bleus.',
                'Tirez une colonne source vers un attribut pour créer l\'alimentation. Déposez sur le corps de la table pour créer l\'attribut au nom de la colonne et le relier dans la foulée. Double-clic sur un attribut pour couper son alimentation.',
                'Auto-alimentation à la création : à l\'ajout d\'une source, les colonnes de même nom sont reliées automatiquement — les traits apparaissent tout de suite. Le bouton « ⚡ auto-alimenter » rejoue ce rapprochement sur les attributs encore vides.',
                'Le pied de la table indique en permanence combien d\'attributs sont alimentés.'] },
            { v: '6.17.0', d: '2026-07-27', t: 'Extraction : vue graphique optionnelle — choisir les colonnes sur le schéma des liens', items: [
                'Nouvelle case à cocher « 🗺️ Vue graphique » en haut de l\'extraction. Elle AJOUTE un schéma au-dessus de l\'écran habituel, qui reste entièrement disponible et synchronisé : rien n\'est remplacé.',
                'Le schéma déplie, depuis la table de départ, l\'arbre des chemins de jointure. Chaque case est une table ATTEINTE PAR UN CHEMIN PRÉCIS, et les traits portent le lien en clair (COLONNE = COLONNE).',
                'Une table reliée plusieurs fois apparaît une fois par lien : cocher la colonne sur la bonne case renseigne le « via » automatiquement — plus besoin de le choisir dans une liste.',
                'Dans chaque case : cocher/décocher une colonne, « tout / rien », renommer la colonne en sortie, choisir sa transformation, poser un filtre (opérateur + valeur) directement sur la ligne.',
                'Sur une table liée : « Σ compter » ajoute en un clic le nombre de lignes liées par ce chemin, et « ⭐ départ » permet de repartir de cette table.',
                'Les cases se déplacent à la souris ou au doigt ; leur position est mémorisée pour la session (et exclue des paramétrages enregistrés).'] },
            { v: '6.16.1', d: '2026-07-27', t: 'Nettoyage : suppression du code de l\'ancien écran d\'extraction', items: [
                'L\'ancien écran d\'extraction « cartes par table » avait été retiré de l\'interface lors de l\'unification (4.0), mais tout son code était resté : écran de sélection, filtres intelligents, moteur JS historique et moteur SQL de première génération. Il ne pouvait plus s\'exécuter — ses conteneurs et son bouton n\'existent plus dans la page.',
                '38 fonctions supprimées, environ 800 lignes : renderExtractionColumns, validateExtractionState, startExtraction, runLegacyExtraction, runSqlExtraction, les filtres intelligents (addFilter, removeFilter, loadFilterValues, rowPassesFilters, buildFilterWhereSql) et divers utilitaires devenus orphelins (mcdHighlightNeighbors, lfReconParts, boElUsageCellHtml, tdDivSql…).',
                'Conservé volontairement : la reprise des anciens paramétrages. Une session ou un fichier d\'échange enregistré avec l\'ancien écran continue d\'être relu et converti vers le moteur actuel — colonnes, transposition, comptage et hiérarchies comprises.',
                'Retiré aussi : le bandeau « Filtres Globaux Actifs », que plus aucun code ne pouvait afficher.',
                'Aucun changement de comportement : cette version ne fait qu\'alléger le fichier.'] },
            { v: '6.16.0', d: '2026-07-27', t: 'Extraction : le choix du chemin s\'applique à TOUTES les fonctionnalités', items: [
                'Le sélecteur « via » n\'existait que sur l\'ajout d\'une colonne simple. Il est maintenant le même composant partout : colonnes calculées (chaque morceau d\'une concaténation, et la colonne source de GAUCHE/DROITE/STXT/NBCAR/SI), filtres, agrégats et leurs critères, synthèses de table liée (Σ) et hiérarchies aplaties.',
                'On peut donc concaténer une même colonne ramenée par DEUX chemins différents (nom du souscripteur « → » nom du bénéficiaire), filtrer sur un chemin et compter sur l\'autre, ou résumer une table liée en précisant par où passer.',
                'Les synthèses et les hiérarchies s\'ancrent désormais sur le chemin choisi : la table parente et son alias suivent ce chemin au lieu de retomber systématiquement sur le chemin par défaut.',
                'Le chemin retenu est rappelé en clair partout où l\'élément est listé : colonnes, pastilles de filtre, agrégats, critères, morceaux de concaténation.',
                'Correction : le rappel « via … » de la liste des colonnes s\'affichait sous forme de balises HTML brutes (régression 6.14). Le libellé est redevenu du texte simple.',
                'Inchangé : rien ne s\'affiche quand il n\'y a qu\'un seul chemin possible, et tout élément sans « via » emprunte le chemin par défaut.'] },
            { v: '6.15.0', d: '2026-07-24', t: 'Extraction : les chemins indirects (tables de liaison) sont aussi proposés au choix', items: [
                'Le choix « via » ne se limitait qu\'aux liens DIRECTS. Il porte désormais un CHEMIN complet : direct, ou passant par une ou plusieurs tables intermédiaires (tables de liaison).',
                'Quand une table est atteignable par PLUSIEURS chemins, la liste déroulante les propose tous, écrits en clair : la suite des tables traversées (⇢ LIEN → CLIENT) puis le détail des jointures (colonne = colonne) de chaque saut.',
                'Le planificateur parcourt le chemin retenu depuis la table de départ et pose un alias SQL dédié à CHAQUE saut, tables intermédiaires comprises — deux chemins qui partagent une table de liaison ne se mélangent donc jamais.',
                'Comme avant : rien ne s\'affiche s\'il n\'y a qu\'un seul chemin, et une colonne sans « via » emprunte le chemin par défaut. Toutes les manipulations (alias, transformations, calculs, filtres, regroupements, agrégats) restent disponibles par chemin.'] },
            { v: '6.14.0', d: '2026-07-24', t: 'Extraction : ramener les données de la MÊME table par plusieurs liens à la fois', items: [
                'La 6.13 ne permettait de choisir qu\'UN lien par couple de tables : impossible de ramener, dans la même extraction, le nom du souscripteur ET celui du bénéficiaire. C\'est corrigé — une table peut désormais être jointe PLUSIEURS FOIS, une fois par lien.',
                'Chaque colonne porte son propre lien : un sélecteur « via » apparaît dans la ligne d\'ajout dès que la table choisie est reliée plusieurs fois. Le lien retenu est rappelé dans la liste des colonnes, et l\'alias de sortie est rendu unique automatiquement.',
                'Toutes les manipulations restent disponibles sur ces colonnes : alias métier, transformations, colonnes calculées (concaténation, GAUCHE/DROITE/STXT/NBCAR/SI), filtres, dédoublonnage, regroupements et agrégats — chacun pouvant viser un lien précis.',
                'Techniquement, le planificateur raisonne désormais par ROUTE (table + lien) et non plus par table : chaque route obtient son propre alias SQL. Le choix « par défaut » de la 6.13 reste et sert aux colonnes qui ne précisent rien.'] },
            { v: '6.13.0', d: '2026-07-24', t: 'Extraction : quand deux tables sont reliées plusieurs fois, on vous demande quel lien utiliser', items: [
                'CORRECTIF DE FOND : si deux tables étaient reliées par PLUSIEURS liens dans le modèle (ex. CONTRAT.souscripteur et CONTRAT.beneficiaire pointant tous deux sur CLIENT), l\'extraction choisissait SILENCIEUSEMENT le premier lien déclaré — le résultat pouvait donc être faux sans aucun signal.',
                'Un encart « 🔗 Quel lien utiliser ? » apparaît désormais dès qu\'une ambiguïté existe sur le chemin de jointure réellement utilisé : une ligne par couple de tables, une simple liste déroulante avec les liens possibles écrits en clair (TABLE.colonne = TABLE.colonne, avec la cardinalité).',
                'Le choix pilote vraiment le SQL généré : la jointure, les synthèses de tables liées et les ancrages de hiérarchie utilisent le lien retenu. Il est mémorisé avec le paramétrage d\'extraction.',
                'Rien ne change quand il n\'y a qu\'un seul lien : l\'encart ne s\'affiche pas et le comportement est identique.'] },
            { v: '6.12.1', d: '2026-07-24', t: 'Correctif : des tables techniques restaient visibles dans la lecture métier', items: [
                'CAUSE 1 : si l\'interrupteur « Objets métier » avait été décoché, aucun lien « compose » n\'était dérivé — donc aucune table ne pouvait être repliée, et la carte n\'affichait que des tables. Pire, la case était masquée en vue métier, donc impossible à rétablir. Les objets métier sont désormais FORCÉS en lecture métier.',
                'CAUSE 2 : le repli s\'arrêtait aux tables composant un objet. Il est maintenant TOTAL — plus aucune table n\'apparaît en lecture métier : table composant un objet → absorbée par l\'objet ; table diffusée par un objet → absorbée par ce même objet ; table restante → absorbée par l\'application qui la produit.',
                'Les tables rattachées à AUCUN objet et AUCUNE application sont écartées de la carte et listées nommément dans le bandeau, avec les deux gestes possibles pour les qualifier.',
                'Un message explicite apparaît quand il n\'existe aucun objet métier : sans objet, il n\'y a rien à lire au niveau métier.'] },
            { v: '6.12.0', d: '2026-07-24', t: 'Gouvernance : « Diffusion » devient « Découvrir » et passe en point d\'entrée', items: [
                'La famille « 🗂️ Diffusion » est renommée « 🧭 Découvrir » et placée EN PREMIER : on entre dans la Gouvernance par le catalogue, c\'est-à-dire par la donnée disponible, avant de descendre vers le patrimoine, les acteurs et le détail.',
                'Le Catalogue devient l\'écran affiché par défaut à l\'ouverture de la Gouvernance (et quand on clique la phase ④ Gouvernance).',
                'Ordre des familles : 🧭 Découvrir · Patrimoine · Acteurs · Sens métier · Lineage · Contrôle. Aucun écran n\'est supprimé ni déplacé de famille.',
                'L\'icône du bouton de phase « Gouvernance » est désormais explicite (📚) et ne dépend plus du premier onglet, pour que le réordonnancement ne change pas la barre de navigation.'] },
            { v: '6.11.0', d: '2026-07-24', t: 'Lineage : le flux se lit en OBJETS MÉTIER, plus en tables', items: [
                'Nouvelle lecture par défaut « 🏛️ Vue métier » : chaque table technique est ABSORBÉE par l\'objet métier qu\'elle compose. Les alimentations entre tables d\'un même objet deviennent internes et disparaissent ; celles entre objets deviennent des liens entre objets métier.',
                'Le graphe ne montre donc plus que ce qui a un sens métier : Applications ▸ Objets métier ▸ Consommateurs. L\'objet affiche un badge « 📦 N tables » (détail au survol).',
                'Les tables encore rattachées à AUCUN objet métier restent visibles et sont listées dans un bandeau dédié, avec le geste pour les rattacher — la vue métier devient ainsi un outil de complétude.',
                'Bascule « 📄 Vue technique » pour retrouver le détail table par table (avec les options « Objets métier » et « Détailler les sources »). Aucune donnée n\'est modifiée : c\'est un repli d\'affichage.'] },
            { v: '6.10.1', d: '2026-07-24', t: 'Confort : les panneaux dépliés ne se referment plus et l\'écran ne remonte plus après une action', items: [
                'BUG CORRIGÉ : supprimer un nœud ou un lien dans « ⚙️ Construire le flux » (Lineage) refermait le panneau, ce qui raccourcissait la page et faisait « remonter » l\'écran. Le panneau reste désormais ouvert.',
                'Correction GÉNÉRIQUE : l\'état déplié de TOUS les panneaux de l\'application est conservé d\'un rafraîchissement à l\'autre (lineage, applications, extraction, règles, objets métier…), y compris quand leur titre contient un compteur qui change.',
                'On ne rouvre que ce que vous aviez ouvert : un panneau que vous avez volontairement replié le reste, et un écran qui ouvre un panneau exprès (mode édition d\'un nœud) continue de le faire.',
                'Le repositionnement du défilement est repassé sur trois frames pour rattraper les contenus qui changent de hauteur après coup (graphe du lineage, grands tableaux).'] },
            { v: '6.10.0', d: '2026-07-24', t: 'Objet métier \u2194 Applications : rattachement automatique dans les deux sens', items: [
                'Puisque c\'est l\'APPLICATION qui est maître du fichier technique, ajouter une source à un objet métier rattache désormais AUTOMATIQUEMENT l\'application qui la produit : rôle maître/contributeur \u2192 « Produite par », rôle destinataire \u2192 « Consommée par ».',
                'Et dans l\'autre sens : rattacher (ou détacher) une source à une application dans « Applications & processus » met à jour tous les objets métier qui utilisent cette source — plus besoin de le ressaisir des deux côtés.',
                'La fiche d\'une application liste maintenant ses « 🏛️ Objets métier alimentés », cliquables pour ouvrir directement la fiche de l\'objet.',
                'Vos rattachements MANUELS sont préservés : seule la partie déduite est retirée quand elle n\'est plus justifiée (source retirée de l\'objet, ou source détachée de l\'application).',
                'Le lineage suit immédiatement : les nœuds et liens « Produit » / « Consommé par » de la carte se mettent à jour sans action.'] },
            { v: '6.9.0', d: '2026-07-24', t: 'Correctif Règles & score : la règle « Cohérence (expression) » comparait les dates comme du texte', items: [
                'BUG CORRIGÉ : « [DATE_FIN] >= [DATE_DEBUT] » comparait les valeurs LEXICOGRAPHIQUEMENT (les sources sont chargées en texte). Une ligne valide 31/12/2023 → 01/01/2024 était donc signalée en erreur, et l\'écran semblait remonter les lignes conformes au lieu des lignes fautives.',
                'BUG CORRIGÉ : comparer une colonne à un nombre (« [MONTANT] >= 100 ») plantait la requête (Binder Error : VARCHAR vs entier).',
                'Les comparaisons sont désormais TYPÉES automatiquement, dans l\'ordre : DATE (jj/mm/aaaa, aaaa-mm-jj, jj-mm-aaaa, jj.mm.aaaa, aaaa/mm/jj, avec ou sans heure), puis NOMBRE (virgule décimale et espaces milliers), puis TEXTE. Les valeurs vides ou non interprétables ne sont jamais comptées en échec.',
                'ET / OU, parenthèses, fonctions SQL (LENGTH…) et opérateurs à l\'intérieur des chaînes littérales sont gérés correctement ; « != » est accepté comme « <> ».',
                'Audit complet de l\'écran : les 8 autres types de règles (non vide, format, plage, liste, intégrité référentielle, condition si… alors…, unicité, fraîcheur) ont été vérifiés un par un sur données réelles — aucun autre défaut trouvé.'] },
            { v: '6.8.0', d: '2026-07-24', t: 'Lineage — les applications déclarées sur un objet métier apparaissent enfin sur la carte', items: [
                'Les applications renseignées dans la fiche d\'un objet métier (« 🖥 Produite par » et « ⚙️ Consommée par ») deviennent de VRAIS nœuds et liens de la Vue systèmes : « Produit » (application → objet) et « Consommé par » (objet → application).',
                'Elles s\'affichent même si elles ne lisent ni n\'écrivent aucune table — c\'est le cas typique d\'un consommateur déclaré uniquement au niveau métier (ex. ORION/LYNX, ENERGY sur l\'objet Emplacement).',
                'Comme tous les liens d\'objet métier, ils sont dérivés automatiquement : ils apparaissent/disparaissent quand on relie ou délie l\'application dans la fiche, et suivent l\'interrupteur « 🏛️ Objets métier ».',
                'Ils n\'affectent ni les rôles de tables ni la santé : ce sont des liens d\'usage (violet), au même titre que lit/écrit.'] },
            { v: '6.7.0', d: '2026-07-24', t: 'Lineage — les sources sont désormais INTÉGRÉES à leur application par défaut', items: [
                'Dans les deux graphes (Vue systèmes et Bout en bout), un fichier source n\'apparaît plus comme une case à part : il est INTÉGRÉ à l\'application qui le produit — c\'est elle le maître, pas le fichier. Les cartes sont beaucoup plus lisibles.',
                'Les liens du fichier sont reportés sur l\'application : une alimentation « fichier → référentiel » devient « application → référentiel », et le lien interne « l\'appli écrit son fichier » disparaît. Les doublons de liens sont fusionnés.',
                'L\'application affiche le nombre de sources qu\'elle contient (badge « 📦 contient N sources », avec leurs noms au survol).',
                'Réversible à tout moment : « 📄 Détailler les sources » (Vue systèmes) et « 📦 Sources dans l\'appli » (Bout en bout) réaffichent chaque fichier séparément. Aucune donnée n\'est perdue — c\'est un simple repli d\'affichage.'] },
            { v: '6.6.0', d: '2026-07-24', t: 'Extraction — hiérarchie aplatie : extraire PLUSIEURS attributs par niveau', items: [
                'La hiérarchie aplatie ne se limite plus à un seul attribut par niveau : on empile plusieurs colonnes (ex. code ET libellé) via « ➕ ajouter l\'attribut ». Chaque niveau produit alors une colonne par attribut (ex. org_niv1_CODE, org_niv1_LIBELLE, …).',
                'Techniquement, la CTE récursive porte une liste de structs par niveau ; un seul attribut reste une liste de scalaires (rétro-compatible avec les paramétrages existants).',
                'Cumulable avec la profondeur, les filtres, synthèses et agrégats ; les réglages sont conservés dans les paramétrages d\'extraction enregistrés.'] },
            { v: '6.5.0', d: '2026-07-24', t: 'V6 Lot 5 — l\'application « référentiel » d\'un objet métier devient un vrai lien du lineage', items: [
                'Quand un objet métier est « représenté par une application » (référentiel/MDM), le lineage trace désormais un VRAI lien application → objet métier (« Représente »), au lieu d\'un simple badge.',
                'Le lien est dérivé automatiquement : il apparaît/disparaît quand on désigne ou retire le référentiel, et l\'application référentiel reste sur la carte tant qu\'elle porte l\'objet.',
                'Il n\'affecte ni les rôles de tables ni la santé (comme les liens Compose/Diffuse) : c\'est une relation documentaire de matérialisation.'] },
            { v: '6.4.0', d: '2026-07-24', t: 'Extraction : concaténer 2 colonnes OU PLUS + extraire un attribut par niveau de hiérarchie', items: [
                'Colonne calculée CONCATENER : on empile désormais 2 colonnes OU PLUS (dans l\'ordre) avec le séparateur de son choix. Les valeurs vides sont ignorées (pas de séparateur orphelin). L\'ancienne concaténation à 2 colonnes reste lisible.',
                'Hiérarchie aplatie : nouveau champ « Attribut à extraire » — chaque niveau peut restituer un ATTRIBUT de la table hiérarchique (ex. le libellé) au lieu de l\'identifiant. La récursion reste indexée sur l\'identifiant ; seule la valeur affichée par niveau change.',
                'Les deux fonctionnent dans le moteur d\'extraction déclaratif (SQL DuckDB), cumulables avec filtres, synthèses, dédoublonnage et agrégats ; les paramétrages enregistrés conservent ces nouveaux réglages.'] },
            { v: '6.3.0', d: '2026-07-24', t: 'V6 Lot 4 — le squelette rendu visible : chaîne aval de l\'application, rien à ressaisir', items: [
                'Bandeau « Modèle » en tête des Applications : 🖥 Application ▸ 📄 Sources ▸ 🏛️ Objet métier ▸ 📥 Consommateurs — le squelette est rappelé partout.',
                'Chaque application affiche sa CHAÎNE AVAL, reconstruite depuis le paramétrage déjà déclaré : ses sources → les objets métier qu\'elles alimentent → les consommateurs de ces objets. On récupère le paramétrage amont au lieu de tout refaire.',
                'Aboutissement du squelette V6 (Lots 1→4) : l\'application possède ses sources, l\'objet métier est alimenté par les applications et peut être porté par un référentiel, et la réconciliation réutilise son mapping. Un seul modèle, décrit une fois.'] },
            { v: '6.2.0', d: '2026-07-24', t: 'V6 Lot 3 — la réconciliation (image par valeur) réutilise le mapping de l\'objet métier', items: [
                'Fini le double paramétrage : sur la fiche d\'une alimentation, un bouton « 🏛️ Mapping objet métier (N) » reprend d\'un clic les attributs déjà mappés dans l\'objet métier commun aux deux tables du lien — au lieu de re-saisir les mêmes colonnes.',
                'Pour chaque attribut d\'objet métier mappé À LA FOIS sur la table source et sur la table cible, la paire (colonne source → colonne cible) est déduite automatiquement, même quand les noms de colonnes diffèrent entre les deux tables.',
                'Le bouton n\'apparaît que si un mapping commun existe ; les attributs déjà présents et la clé ne sont pas re-ajoutés. Le paramétrage de l\'objet métier devient la source de vérité unique, réutilisée par la mesure de distorsion.'] },
            { v: '6.1.0', d: '2026-07-24', t: 'V6 Lot 2 — l\'objet métier est alimenté PAR les applications (et peut être représenté par un référentiel)', items: [
                'Chaque source d\'un objet métier affiche désormais l\'APPLICATION qui la produit (« via 🖥 … »), matérialisant le principe : la donnée entre dans l\'objet métier via une application, jamais directement depuis un fichier.',
                'Nouveau — « 🏛️ Référentiel : représenté par l\'application » : on peut désigner l\'application qui matérialise/porte l\'objet métier (un MDM, un référentiel client). Le badge apparaît sur le nœud de l\'objet dans le lineage.',
                'Cohérence du modèle : une source d\'objet métier non rattachée à une application est signalée (⚠ sans application) — on rattache la source à son application (Lot 1) pour lever l\'alerte.',
                'Aucune régression : les rôles maître/contributeur/destinataire, les règles de maîtrise contextuelle (ventilation/périmètre) et « Produite/Consommée par » restent inchangés.'] },
            { v: '6.0.0', d: '2026-07-24', t: 'Studio Data V6 — squelette simplifié : Application ▸ Sources ▸ Objet métier ▸ Consommateurs (Lot 1)', items: [
                'NOUVEAU FICHIER StudioDataV6.html : reprend 100 % de V5 (aucune perte) et engage la simplification du modèle de gouvernance autour d\'un squelette unique : une Application possède ses Sources, qui alimentent des Objets métier, qui alimentent des Consommateurs.',
                'Lot 1 — « L\'application possède ses sources » : dans l\'onglet Applications & processus, chaque application déclare désormais les SOURCES (fichiers chargés) dont elle est maître, par simple case à cocher. C\'est l\'application qui est maître, jamais le fichier.',
                'Une source n\'a qu\'un seul propriétaire : la rattacher à une application la retire automatiquement d\'une autre. Le rattachement pilote directement le lineage (lien « écrit → source », rôle Source, application productrice/maître).',
                'Rétro-compatibilité totale : l\'ancien champ « Système source » du dictionnaire est migré automatiquement en rattachements, et reste synchronisé (renommer l\'application met à jour ses sources). Rien à ressaisir.',
                'Prochains lots : objet métier alimenté par les applications (règles de ventilation/maîtrise/périmètre), réutilisation du mapping dans la réconciliation (image par valeur), nettoyage du vocabulaire.'] },
            { v: '5.16.1', d: '2026-07-24', t: 'Correctif Lineage : la règle de fraîcheur d\'un lien est enfin évaluée (SLA du lien)', items: [
                'Le SLA de fraîcheur saisi sur une alimentation (ex. « ≤ 168 h ») était affiché mais JAMAIS pris en compte : le verdict ne dépendait que de la « Fréquence de mise à jour » du dictionnaire de l\'aval. Sans fréquence au dictionnaire, la fraîcheur restait « non mesurée » quel que soit le SLA saisi.',
                'Désormais, dès qu\'un SLA (h) est renseigné sur le lien et que l\'aval a un chargement daté, la fraîcheur est jugée contre CE SLA : ✕ dépassé / ⚠ proche / ✓ respecté, avec le retard réel affiché.',
                'À défaut de SLA sur le lien, on retombe sur la fréquence du dictionnaire (comportement d\'avant). La fiche du lien indique clairement sur quelle base le verdict est calculé.',
                'La couleur du lien sur la carte et l\'étiquette « ⟳ retard » suivent la même règle : le SLA du lien pilote enfin la santé de fraîcheur de l\'alimentation.'] },
            { v: '5.16.0', d: '2026-07-24', t: 'Modèle clair (R2) : la carte est une projection des données — « Tout redériver »', items: [
                'La carte Lineage est officiellement une PROJECTION de vos données : elle se met déjà à jour à chaque ouverture (synchro auto) et à chaque (dé)clic dans les applications.',
                'Nouveau bouton « ♻️ Tout redériver (carte propre) » : reconstruit la carte à neuf à partir des sources de vérité (tables conçues, propriétaire/origine, applications, objets métier) et RETIRE les nœuds/liens ajoutés à la main qui ne correspondent plus à une donnée.',
                'Vos POINTS DE MESURE (clés, attributs contrôlés, transformations, contrôles, nature, périmètre) et vos POSITIONS manuelles sont réattachés automatiquement par identité — rien de votre travail de contrôle n\'est perdu.',
                'C\'est l\'aboutissement de la remise au propre : on déclare les faits (qui contient quoi, qui alimente qui), la carte suit ; un clic suffit à repartir d\'une carte 100 % fidèle aux données.'] },
            { v: '5.15.0', d: '2026-07-24', t: 'Modèle clair (R4) : navigation Gouvernance regroupée + vocabulaire unifié', items: [
                'Les sous-onglets de Gouvernance sont regroupés en 6 familles cohérentes avec le modèle : 🗃️ Patrimoine (Dictionnaire, Modèle de données), 🖥️ Acteurs (Applications & processus), 🧭 Sens métier (Objets métier, Glossaire, Périmètres, Sensibilité), 🕸️ Lineage, 🩺 Contrôle (Surveillance des sources, Historique), 🗂️ Diffusion (Catalogue).',
                'Fini le fourre-tout « Définir » qui mélangeait le physique (dictionnaire), les acteurs (applications) et le sens métier (objets, glossaire) : chaque écran est désormais rangé selon ce qu\'il décrit.',
                'Vocabulaire harmonisé : Table / Application / Objet métier partout (« Modèle de données », « Applications & processus », « Surveillance des sources »).'] },
            { v: '5.14.0', d: '2026-07-24', t: 'Modèle clair (R3) : maîtrise unifiée + panneau « Cohérence du modèle »', items: [
                'La maîtrise est désormais calculée d\'UNE seule façon (l\'application propriétaire d\'une table) et le lineage signale les CONTRADICTIONS entre déclarations dans un panneau « 🧩 Cohérence du modèle ».',
                'Contradictions détectées (⛔) : une table avec deux applications propriétaires ; un objet métier à ≥ 2 sources « maître » sans conditions disjointes.',
                'Points à surveiller (⚠) : une correction sans périmètre vers une table qui a un propriétaire ; un objet métier sans source « maître » désignée ; une table qui alimente en aval sans application propriétaire (origine) renseignée.',
                'Ce panneau remplace l\'ancien bandeau de conflit de maîtrise et centralise toutes les incohérences structurelles à corriger.'] },
            { v: '5.13.0', d: '2026-07-24', t: 'Modèle clair (2/2) : le lien « alimente » enrichi (nature · périmètre · maîtrise)', items: [
                'Chaque alimentation table→table porte désormais une NATURE : « Recopie » (copie à l\'identique), « Complément » (ajoute des colonnes) ou « Correction » (modifie des valeurs poussées par une autre source). La « Consolidation » reste déduite (cible à ≥ 2 sources).',
                'Nouveau champ « Périmètre » sur un lien : le sous-ensemble alimenté (ex. « type = ASSURANCE ») — pour représenter les données qui viennent de sources différentes selon le périmètre. Affiché sur l\'étiquette (⛊) et la fiche du lien.',
                'MAÎTRISE : un lien de nature « Correction » vers une table produite par une AUTRE application déclenche un rappel dans la fiche — si le périmètre n\'est pas disjoint d\'un autre écrivain, c\'est un conflit de maîtrise à arbitrer.',
                'Ferme la fondation du modèle clair : Applications (qui contiennent des tables, dont Référentiel et Rapport) reliées par des flux « alimente » qualifiés — tout le reste (maître, consolidation, santé) reste déduit.'] },
            { v: '5.12.0', d: '2026-07-24', t: 'Modèle clair (1/2) : l\'application CONTIENT ses tables + le Rapport terminal', items: [
                'Première étape de la remise au propre du modèle. Une APPLICATION « contient » (produit / possède) les tables qu\'elle écrit : badge « 📦 contient N » sur le nœud, et sa fiche liste ses tables contenues et lues.',
                'Le champ d\'un nœud table est clarifié : « Application propriétaire (origine) » — l\'application qui produit et possède la table (elle en est le maître). La saisie propose les applications déjà déclarées.',
                'Nouveau type « 📑 Rapport (terminal) » : une application qui restitue la donnée (rapport, tableau de bord) et ne l\'alimente pas plus loin — case à cocher dans le formulaire de nœud, icône et badge dédiés.',
                'Aucune perte : rien n\'est retiré, ce sont des clarifications de vocabulaire et d\'affichage. Étape suivante (2/2) : le lien « alimente » enrichi (nature : recopie / consolidation / complément / correction · périmètre · maîtrise).'] },
            { v: '5.11.1', d: '2026-07-24', t: 'Correctif : les règles de « Règles & score » sont prises en compte dans l\'audit de l\'objet métier', items: [
                'Bug corrigé : les règles de qualité déclarées dans « 📏 Règles & score » n\'étaient pas exécutées par « Lancer l\'audit global de l\'objet » (seules les règles métier de cardinalité l\'étaient).',
                'L\'audit d\'un objet métier exécute désormais aussi les RÈGLES DE QUALITÉ qui le concernent : celles déclarées SUR l\'objet, et celles portant sur une table de son périmètre (maître + sources + composants). Chaque règle affiche son taux de conformité, ses lignes en échec et un accès aux lignes fautives.',
                'Visibilité : l\'onglet Audit de l\'objet liste désormais les règles de qualité rattachées (avec leur dernier résultat) et un raccourci « Gérer dans Règles & score ». Une règle créée sur l\'objet apparaît donc directement dans l\'objet.'] },
            { v: '5.11.0', d: '2026-07-24', t: 'Lineage : objets métier sur la « Vue systèmes » + bouton « Réorganiser »', items: [
                'La « Vue systèmes » affiche désormais les OBJETS MÉTIER (cases vertes 🏛️). Chaque objet est relié à ses tables : ses sources maître/contributeur le « composent » (table → objet), ses destinataires le « diffusent » (objet → table). Ces liens n\'affectent pas les rôles des tables.',
                'Interrupteur « 🏛️ Objets métier » (en haut) pour les afficher/masquer — affichés par défaut. Dérivés et resynchronisés automatiquement avec la gouvernance ; masquer les retire proprement de la carte.',
                'Nouveau bouton « ⇄ Réorganiser » (toujours disponible) : réorganise la carte automatiquement (efface les déplacements manuels et recalcule la disposition amont → aval).'] },
            { v: '5.10.0', d: '2026-07-24', t: 'Lineage : le MAÎTRE est l\'application, pas le fichier (l\'origine devient une application productrice)', items: [
                'Correction de fond : un fichier source ne peut pas être « maître ». Le maître de la donnée est l\'APPLICATION amont (ex. KADOR). Désormais, l\'ORIGINE (système amont) d\'un fichier est matérialisée en nœud 🖥 Application qui PRODUIT (écrit) ce fichier.',
                'Le fichier produit prend le rôle « 📄 Source » (extrait) et n\'est plus étiqueté « Maître » ; le rôle maître est porté par l\'application productrice (badge « 🗄 maître »), placée en amont. Les fichiers appartiennent ainsi à une application.',
                'La production est reliée à l\'application déclarée dans « Applis & processus » quand le nom correspond (même nœud pour produire ET consommer, cas de l\'écriture en retour). Dérivé et resynchronisé automatiquement ; réglages manuels préservés.',
                'Un fichier redevient « Maître » uniquement s\'il n\'a AUCUNE origine renseignée (renseignez le « Système source » au dictionnaire pour rétablir la chaîne application → fichier).'] },
            { v: '5.9.1', d: '2026-07-24', t: 'Lineage : la « Vue systèmes » est resynchronisée à l\'ouverture (cohérence avec « Bout en bout »)', items: [
                'La carte « Vue systèmes/attributs » et le graphe « Bout en bout » lisaient deux sources différentes : le premier n\'était à jour qu\'après un clic sur « Synchroniser », le second se dérive en direct — d\'où une impression de désynchronisation.',
                'Désormais, ouvrir l\'onglet Lineage RESYNCHRONISE automatiquement la « Vue systèmes » avec vos données (tables conçues + applications), en silence et en préservant vos réglages manuels : les deux vues reflètent toujours les mêmes faits.',
                'Rappel des rôles : « Vue systèmes » = carte centrée sur les tables & applications MESURABLES (fraîcheur, distorsion, conflits) ; « Bout en bout » = graphe complet incluant en plus les objets métier et les relations du modèle.'] },
            { v: '5.9.0', d: '2026-07-24', t: 'Lineage : la déclaration d\'usage pilote la carte (ajout ET retrait, mise à jour auto)', items: [
                'La synchronisation RÉCONCILIE désormais les liens d\'usage dérivés : elle ajoute les nouveaux « lit »/« écrit » ET RETIRE ceux devenus obsolètes (table décochée sur l\'application). Une application dérivée qui n\'utilise plus rien est retirée. Vos liens ajoutés à la main et vos réglages (clés, attributs, contrôles) restent préservés.',
                'MISE À JOUR AUTOMATIQUE : dans « Applis & processus », cocher/décocher une table ou lier/délier une colonne d\'une application DÉJÀ présente sur le lineage met la carte à jour immédiatement — plus besoin de repasser par le bouton « Synchroniser ».',
                'Le récapitulatif de synchro détaille désormais les ajouts ET les retraits (liens obsolètes, applications orphelines).'] },
            { v: '5.8.0', d: '2026-07-24', t: 'Lineage : « Contrôler toute la chaîne aval » depuis un nœud', items: [
                'Nouveau bouton « ↻ Contrôler toute la chaîne aval (N) » dans la fiche d\'un nœud : relance en une fois la réconciliation de TOUTES les alimentations situées en aval (parcours récursif des liens « alimente »).',
                'Idéal après une écriture en retour (write-back) : quand une application resynchronise un référentiel, un seul clic revérifie la cohérence de toutes les copies aval et le compte total de lignes en écart.',
                'Seules les alimentations réellement contrôlables (source + cible chargées, clé et attribut renseignés) sont exécutées ; le récapitulatif indique le nombre vérifié et le total d\'écarts.'] },
            { v: '5.7.0', d: '2026-07-24', t: 'Lineage : nœuds déplaçables + applications, écriture en retour & consommation partielle', items: [
                'Les nœuds sont désormais DÉPLAÇABLES : glissez-les (souris ou tactile) pour composer votre carte ; la position est mémorisée. Bouton « ↺ Disposition auto » pour revenir à l\'agencement automatique.',
                'On peut créer un nœud « 🖥 Application » à la main (champ « Nature » du formulaire). La nature d\'un lien est alors DÉDUITE des types reliés : application en source = « écrit », en cible = « lit », sinon table→table = « alimente ». Plus besoin de choisir.',
                'ÉCRITURE EN RETOUR (write-back) : une application qui LIT et ÉCRIT la même table est repérée (badge « ↺ écriture en retour »). Sa fiche explique que ses modifications resynchronisent le référentiel et, en cascade, les copies aval et les consommateurs — avec un rappel de contrôler les alimentations qui en partent.',
                'CONSOMMATION PARTIELLE : un lien de lecture peut déclarer un SOUS-ENSEMBLE d\'attributs consommés (via le champ « Attribut » du lien). La fiche affiche « consommation partielle — N attribut(s) » ou « toutes les colonnes ».'] },
            { v: '5.6.0', d: '2026-07-24', t: 'Lineage : un seul onglet — structure, santé & graphe de bout en bout (lot 4)', items: [
                'Fin des deux onglets « Lineage » et « Lineage & santé » : un SEUL onglet « 🕸️ Lineage » regroupe tout. La vue par défaut est la carte table-centrée avec la santé (fraîcheur, distorsion, conflits) ; un bouton « 🕸️ Bout en bout » bascule vers le graphe complet sources ↔ tables ↔ objets métier ↔ applications, et « ◀ Structure & santé » y ramène.',
                'Aucune perte : toutes les capacités de l\'ancien onglet Lineage (vue globale, par attribut, filtres, plein écran, export image, mise en évidence de chaîne) restent disponibles dans la vue « Bout en bout ». Les liens « voir le lineage » du catalogue et de l\'analyse d\'impact ouvrent directement cette vue.',
                'Aboutissement du redesign table-centré : moins de concepts, une carte dérivée des données réelles (Synchroniser), et une santé mesurée là où elle a un sens — le tout sur un écran unique.'] },
            { v: '5.5.0', d: '2026-07-24', t: 'Lineage : couche application — lit / écrit & conflits de maîtrise (lot 3)', items: [
                'La synchronisation dérive désormais la COUCHE APPLICATION : chaque application/processus devient un nœud 🖥 relié aux tables qu\'il utilise par un lien « lit » (table → application), et, s\'il est déclaré « Système source » d\'une table au dictionnaire, par un lien « écrit » (application → table).',
                'Fraîcheur HÉRITÉE : une application prend la pire fraîcheur des tables qu\'elle lit ; pas de distorsion propre (la donnée consommée EST celle de la table). L\'analyse d\'impact indique combien d\'applications sont touchées par un problème sur une table.',
                'Détection des CONFLITS DE MAÎTRISE : un bandeau d\'alerte signale les objets métier ayant ≥ 2 sources « maître » sans conditions disjointes (deux maîtres qui se chevauchent) ; il invite à séparer les périmètres par une règle de maîtrise contextuelle ou à désigner un maître unique.',
                'Le rôle et la consolidation restent déduits des seules alimentations : les liens d\'usage (lit/écrit) ne faussent pas la topologie. Nœuds application en violet pointillé, liens d\'usage distincts dans le graphe et les fiches.'] },
            { v: '5.4.0', d: '2026-07-24', t: 'Lineage : « Synchroniser depuis les données » (lot 2)', items: [
                'Nouveau bouton « 🔄 Synchroniser depuis les données » dans le constructeur de flux : les alimentations sont DÉRIVÉES automatiquement de vos TABLES CONÇUES — chaque table conçue devient une cible alimentée par ses sources contributrices (colonne SOURCE_ORIGINE) et ses sources d\'enrichissement.',
                'Fusion additive par identité : les nœuds sont rapprochés par nom de table, les liens par couple source → cible. Rien n\'est écrasé ni supprimé — vos réglages manuels (clés, attributs contrôlés, SLA, transformations, derniers contrôles) sont intégralement préservés.',
                'L\'origine (système amont) des nouveaux nœuds est renseignée automatiquement depuis le « Système source » du dictionnaire quand il est vide. Les éléments issus de la synchro portent un discret badge « 🔄 auto ».',
                'Fini la re-saisie de la carte : une table conçue à ≥ 2 sources apparaît directement comme consolidation (badge déduit).'] },
            { v: '5.3.0', d: '2026-07-24', t: 'Lineage : modèle table-centré — rôle & consolidation déduits (lot 1)', items: [
                'Chaque nœud du flux représente désormais une TABLE ; on ne saisit plus son rôle à la main. Le rôle (Maître / Référentiel / Consommateur) est DÉDUIT automatiquement de la topologie : aucune alimentation entrante = Maître (source de vérité), deux alimentations entrantes ou plus = Référentiel (consolidation), sinon Consommateur.',
                'Nouvelle information « Origine (système amont) » sur chaque nœud : le système d\'où provient la table (SAP, saisie manuelle…), distinct de la table elle-même. Elle s\'affiche sous le nom du nœud, dans la liste et dans la fiche.',
                'Le type de lien n\'est plus saisi non plus : il est DÉDUIT (« Consolide » quand la cible reçoit ≥ 2 sources, sinon « Alimente »). Un badge « ⑃ consolide » signale les tables consolidées dans le graphe et les listes.',
                'Rétro-compatible : les flux existants s\'affichent avec les rôles et types recalculés d\'après leurs liens, sans perte ni ressaisie. La réconciliation, la fraîcheur et la santé attribut par attribut restent identiques.'] },
            { v: '5.2.1', d: '2026-07-23', t: 'Correctif : onglets de Surveillance des sources', items: [
                'Correction d\'un bug o\u00f9 les sous-onglets de « Surveillance des sources » (Moniteur & fra\u00eecheur, Contrat de donn\u00e9es, Changements/delta, R\u00e9conciliation) ne r\u00e9agissaient pas au clic : le changement d\'outil est d\u00e9sormais bien appliqu\u00e9 et l\'\u00e9cran se met \u00e0 jour.'] },
            { v: '5.2.0', d: '2026-07-23', t: 'Lineage : santé d\'une alimentation ATTRIBUT PAR ATTRIBUT', items: [
                'Un lien peut désormais contrôler PLUSIEURS attributs (et non plus un seul) : chaque attribut a sa paire colonne source → colonne cible et sa propre transformation rejouable.',
                'La réconciliation renvoie la distorsion GLOBALE (lignes avec au moins un écart) ET le détail par attribut (taux, barre, exemples) : la santé complète d\'une alimentation se lit d\'un coup d\'œil.',
                'Fiche du lien (clic sur son étiquette) : gestionnaire des attributs contrôlés — ajout (colonne source → colonne cible + transformation), retrait, et « ✚ Même nom » pour ajouter d\'un coup toutes les colonnes de même nom présentes des deux côtés. Le bouton « Contrôler N attribut(s) » lance la vérification complète ; l\'export CSV couvre tous les attributs.'] },
            { v: '5.1.3', d: '2026-07-23', t: 'Édition partout : règles métier & renommage des paramétrages', items: [
                'Règles métier de cardinalité (« 1 X doit avoir exactement N Y quand … ») : désormais MODIFIABLES en ligne après création — opérateur (exactement / au plus / au moins), nombre N, valeur de la condition et libellé — au lieu d\'être en lecture seule (supprimer/recréer).',
                'Paramétrages d\'extraction : ajout du renommage (bouton ✎) en plus de charger / enregistrer / supprimer.',
                'Passe d\'édition sur toute l\'application : le reste des entités (dictionnaire, objets métier, glossaire, périmètres, applications & processus, règles qualité, préparations, connecteurs, rapprochements, tableaux de bord, sensibilité, tables conçues, lineage) était déjà modifiable en ligne — ces deux points fermaient les derniers écarts.'] },
            { v: '5.1.2', d: '2026-07-23', t: 'Lineage : clé/attribut par côté + édition des liens et nœuds', items: [
                'La clé et l\'attribut d\'un lien se déclarent désormais SÉPARÉMENT côté source et côté cible (leurs noms diffèrent souvent d\'une source à l\'autre, ex. « DK code » vs « DK_CODE_CTT ») ; la réconciliation joint et compare avec le bon nom de chaque côté.',
                'Chaque champ propose les colonnes de SA propre source reliée (fini l\'intersection vide quand les noms diffèrent).',
                'Édition : les nœuds ET les liens déjà créés se modifient (bouton ✎) — le formulaire se pré-remplit ; un lien modifié réinitialise son dernier contrôle. Compatibilité ascendante des liens créés avant (clé/attribut uniques repris des deux côtés).'] },
            { v: '5.1.1', d: '2026-07-23', t: 'Lineage : clé & attribut proposés', items: [
                'Constructeur de flux : les champs « Clé commune » et « Attribut comparé » d\'un lien proposent désormais les colonnes des sources reliées (les colonnes COMMUNES à la Source et à la Cible), rafraîchies au changement de Source/Cible. La saisie manuelle reste possible en secours.'] },
            { v: '5.1.0', d: '2026-07-23', t: 'Lineage augmenté : vue attributs, transformation rejouable, journal', items: [
                'Bascule « Vue systèmes / Vue attributs » : le même flux au niveau colonne — chaque nœud liste ses attributs reliés (clé + attribut comparé) et les liens portent l\'attribut concerné.',
                'Transformation REJOUABLE sur un lien (agrégation SOMME/MOYENNE/MIN/MAX/NOMBRE par clé, ou normalisation scalaire : arrondi, × facteur, valeur absolue, casse, espaces) : la réconciliation compare l\'aval au maître TRANSFORMÉ par la règle, plus au maître brut — un écart attendu ne ressort plus comme distorsion, et un écart résiduel malgré la règle est signalé comme anomalie.',
                'Journal des contrôles & alertes persistant : chaque réconciliation est horodatée (flux, taux, écarts, clés manquantes, transformation rejouée, statut), avec compteur d\'alertes et purge.'] },
            { v: '5.0.0', d: '2026-07-23', t: 'Lineage augmenté & réconciliation (santé du flux)', items: [
                'Nouvel écran Gouvernance ▸ Tracer ▸ « 🔗 Lineage & santé » : la carte du flux d\'un objet, de l\'application maître jusqu\'aux consommateurs, enrichie de deux contrôles posés sur les données réelles.',
                'Graphe orienté maître → référentiel → consommateurs (moteur SVG maison), badges de rôle, pastilles de santé, arêtes colorées par état (sain / à surveiller / alerte) et étiquettes « ⟳ retard · Δ distorsion ».',
                'Fraîcheur : retard de chaque copie aval calculé depuis la dernière mise à jour et la fréquence attendue du dictionnaire (SLA), avec statut ok / à surveiller / dépassé.',
                'Réconciliation (DuckDB) : taux de distorsion entre le maître et l\'aval sur une clé commune et un attribut comparé, volumétrie (clés manquantes en aval), exemples d\'écarts clé/maître/aval et export CSV — calcul sans débordement (runNoSpill).',
                'Constructeur de flux : ajout de systèmes (rôle, domaine, source liée) et de liens (type, clé, attribut, SLA, transformation déclarée) ; amorçage automatique depuis les objets métier ; seuil de distorsion configurable ; bandeau de synthèse (SLA respectés, distorsions au-dessus du seuil, flux le plus en retard, dernier contrôle).',
                'Distinction écart attendu / anomalie : une transformation déclarée sur un lien explique un écart normal ; une distorsion sans transformation est signalée comme anomalie probable.',
                'Tout est persisté localement avec la gouvernance ; aucune dépendance nouvelle ; V3 reste inchangé (nouveau fichier StudioDataV5.html).'] },
            { v: '4.6.0', d: '2026-07-23', t: 'Paramétrages d\'extraction enregistrables', items: [
                'Nouvel encart « 💾 Paramétrages d\'extraction » en haut de l\'extraction avancée : enregistrez sous un nom toute la configuration (table de départ, colonnes et alias métier, transformations, colonnes calculées, synthèses de tables liées, hiérarchies aplaties, filtres, dédoublonnage, regroupements et agrégats, type de jointure), puis rechargez-la ou supprimez-la en un clic.',
                'Les paramétrages sont stockés par NOM de source (donc rejouables d\'une session à l\'autre) et conservés dans le stockage local avec le reste de votre travail. Au chargement, tout élément renvoyant à une source absente est signalé et ignoré proprement.'] },
            { v: '4.5.3', d: '2026-07-23', t: 'Audit d\'objet & Surveillance sources : fin des blocages sur grosses sources', items: [
                'Correction de « l\'audit global de l\'objet » et des outils de « Surveillance des sources » (instantané, contrat, delta, réconciliation) qui restaient sans effet ou en erreur sur de très grosses sources lues à la demande, en contexte fichier local (file://).',
                'Même correctif que le rapport d\'écarts : ces analyses (comptages, jointures, dédoublonnages) s\'exécutent désormais sans jamais déborder sur disque (mémoire relevée, débordement coupé), ce qui supprime l\'erreur « HTML FileReaders do not support writing » et fiabilise les résultats.'] },
            { v: '4.5.2', d: '2026-07-23', t: 'Rapport d\'écarts : fin de « FileReaders do not support writing »', items: [
                'Correctif DÉFINITIF de « Analyse impossible : HTML FileReaders do not support writing » sur le rapport d\'écarts entre sources. Cause : lancée depuis un fichier local (file://), l\'application n\'a aucun stockage temporaire inscriptible et la moindre agrégation qui débordait échouait.',
                'L\'analyse ne déborde plus JAMAIS sur disque : limite mémoire relevée, débordement désactivé, et surtout jeu de travail réduit — projection légère matérialisée puis comparaison ATTRIBUT PAR ATTRIBUT. Chaque étape tient en mémoire ; aucune action « Optimiser » n\'est requise, tout est automatique. L\'export CSV suit la même stratégie.'] },
            { v: '4.5.1', d: '2026-07-23', t: 'Correctifs DuckDB : optimisation & rapport d\'écarts', items: [
                'Optimisation Parquet : correction de « unique_lock::unlock: not locked » — les requêtes DuckDB sont désormais sérialisées (le moteur n\'est pas réentrant), avec un ré-essai sur verrou transitoire.',
                'Rapport d\'écarts entre sources : l\'analyse matérialise d\'abord une projection légère (clé + attributs) en mémoire, ce qui supprime l\'erreur « HTML FileReaders do not support writing » sur les grosses tables lues à la demande et accélère fortement le calcul.'] },
            { v: '4.5.0', d: '2026-07-23', t: 'Surveillance des sources amont', items: [
                'Nouvel écran Gouvernance ▸ Tracer ▸ « 🛰️ Surveillance sources » avec 4 outils autour d\'une source rafraîchie depuis une application amont :',
                'Moniteur & fraîcheur : instantanés (volumétrie + schéma), dérive de schéma (colonnes ajoutées/supprimées/retypées) et de volumétrie, alerte de retard selon la fréquence de mise à jour du dictionnaire (SLA).',
                'Contrat de données : schéma attendu (généré depuis la structure), colonnes obligatoires, et vérification de conformité (manquantes, types différents, obligatoires vides, colonnes en plus).',
                'Suivi des changements (delta) : figer un instantané des données puis comparer l\'état actuel — lignes ajoutées / supprimées / modifiées / inchangées par clé.',
                'Réconciliation amont/aval : volumétrie et orphelins (clés non recoupées) entre deux sources par leur clé.'] },
            { v: '4.4.3', d: '2026-07-23', t: 'Correctif : analyse d\'écarts sur grosses tables', items: [
                'Correction du « Analyse impossible : HTML FileReaders do not support writing » sur le rapport d\'écarts entre sources d\'une grosse table lue à la demande : l\'analyse se relance automatiquement en mémoire pure quand le stockage temporaire du navigateur n\'est pas inscriptible, avec un message d\'aide clair si le volume reste trop élevé.'] },
            { v: '4.4.2', d: '2026-07-23', t: 'Import : diagnostic « objet introuvable »', items: [
                'Import en masse : quand des lignes sont ignorées pour « objet métier introuvable », le rapport liste les objets métier réellement existants — pour repérer aussitôt un écart d\'orthographe (espace, pluriel, code…).'] },
            { v: '4.4.1', d: '2026-07-23', t: 'Import en masse : rapport d\'erreurs détaillé', items: [
                'Import en masse : le rapport ventile désormais les lignes ignorées PAR MOTIF, avec des exemples (ex : « objet métier introuvable — créez-le d\'abord », « lien déjà enregistré », « clé vide »…), pour comprendre d\'un coup d\'œil pourquoi une ligne n\'est pas passée.'] },
            { v: '4.4.0', d: '2026-07-23', t: 'Import en masse : objets métier & applications par objet', items: [
                'Import en masse : nouvelle cible « 🏛 Objets métier » — créer/mettre à jour des objets métier (définition, propriétaire, attributs séparés par ;, table source maître).',
                'Import en masse : nouvelle cible « Applications par objet métier » — rattacher au niveau objet quelle application utilise (ou produit) quel objet métier, en une seule ligne.',
                'Modèles d\'alimentation pré-remplis fournis pour les deux, avec vos objets et liens existants.'] },
            { v: '4.3.2', d: '2026-07-23', t: 'Lineage de la fiche agrandi', items: [
                'Catalogue : le graphe de lineage affiché dans la fiche élargit le panneau et occupe une plus grande zone, avec un bouton « Agrandir » (plein écran) — il n\'est plus à l\'étroit.'] },
            { v: '4.3.1', d: '2026-07-23', t: 'Fiche d\'un attribut recentrée', items: [
                'Catalogue : la fiche d\'un attribut affiche désormais le détail de CET attribut (type réel, type déclaré, complétude, terme, table) au lieu de la structure complète (toutes les colonnes) de sa table.'] },
            { v: '4.3.0', d: '2026-07-23', t: 'Lineage d\'un attribut depuis le catalogue', items: [
                'Catalogue : « Voir le lineage » sur un attribut affiche le graphe nœuds-liens de son lineage (système source → colonne → attribut → applications/processus qui l\'utilisent) directement dans la fiche, au lieu d\'ouvrir le lineage global.'] },
            { v: '4.2.0', d: '2026-07-23', t: 'Encodage des sources', items: [
                'Sources : choix de l\'encodage étendu (UTF-8, Windows/ANSI Latin-1, UTF-16).',
                'Détection automatique des caractères illisibles (mojibake) avec correction en un clic, et ré-essai automatique de l\'encodage quand l\'import échoue sur une erreur unicode — un « faux problème de données » est souvent un simple souci d\'encodage.'] },
            { v: '4.1.0', d: '2026-07-23', t: 'Parcours d\'un attribut au clic', items: [
                'Lineage « Par attribut » : cliquer un attribut affiche une mini-carte de parcours « d\'où vient la donnée (application source + colonnes) → cet attribut → où elle est utilisée (consommateurs) », en plus de l\'isolement de sa chaîne dans le flux.'] },
            { v: '4.0.0', d: '2026-07-23', t: 'Extraction unifiée', items: [
                'Les deux parties de l\'écran Extraction (« Table principale » et « Extraction avancée ») fusionnent en UNE seule configuration déclarative, sans perte de fonctionnalités.',
                'Nouveaux types de colonnes : « Synthèse d\'une table liée » (compter les lignes, compter les valeurs uniques, transposer en texte ou en colonnes) et « Hiérarchie aplatie » (même table ou table de liaison, période de validité, date de référence, profondeur) — désormais en SQL pur, cumulables avec alias, dédoublonnage et agrégats.',
                'Ajout de colonnes en masse (« ➕ Plusieurs colonnes… ») depuis n\'importe quelle table du modèle, avec recherche.',
                'Filtres enrichis : dans la liste (;), ≥/≤ numérique, à partir du / jusqu\'au (date).',
                'Type de jointure (conserver tout / intersection) et mode aperçu 500 lignes conservés.',
                'Les anciennes configurations (colonnes cochées, modes, hiérarchies, filtres) sont converties automatiquement.'] },
            { v: '3.8.0', d: '2026-07-23', t: 'Règles qualité sur objets métier & listes filtrables', items: [
                'Règles de qualité : la cible peut être un OBJET MÉTIER — choisissez l\'objet puis l\'attribut ; la règle est contrôlée sur chaque source où l\'attribut est mappé, puis agrégée (tous les types : non vide, format, plage, liste, unicité, condition si… alors…, fraîcheur…).',
                'Auto-complétion sur toutes les listes déroulantes d\'au moins 8 choix : tapez pour chercher (accents ignorés), Entrée valide, Échap annule.'] },
            { v: '3.7.0', d: '2026-07-22', t: 'Fusion cas d\'usage → processus, domaines', items: [
                'Les « cas d\'usage » fusionnent dans Applis & processus : vos cas d\'usage existants sont migrés automatiquement en processus, sans perte (nom, responsable, criticité, tables, colonnes critiques, objets métier, applications).',
                'Un processus s\'appuie désormais sur une ou plusieurs applications, et déclare les tables et colonnes qu\'il utilise.',
                'Domaine métier sur les applications et les processus (hérité automatiquement des applications liées si non saisi).',
                'Analyse d\'impact, lineage, catalogue, check-list objet et import en masse rebranchés sur les processus.'] },
            { v: '3.6.0', d: '2026-07-22', t: 'Règles conditionnelles & versionnage', items: [
                'Règles de qualité : nouveau type « Condition (si… alors…) » — si un attribut est rempli, vide, ou vaut une valeur (fixe ou dans une liste), alors un autre attribut doit être vide, rempli, ou valoir une valeur (fixe ou dans une liste).',
                'Numéro de version affiché dans l\'en-tête, avec ces notes de version.'] },
            { v: '3.5.0', d: '2026-07-22', t: 'Préparation de données', items: [
                'Les « Recettes » deviennent « 🧹 Préparation de données », avec une explication intégrée à l\'écran (problème, solution, exemple).',
                'Les tables produites sont préfixées PROPRE_.'] },
            { v: '3.4.0', d: '2026-07-22', t: 'Catalogue consommateur de données', items: [
                'Recherche héros avec exemples et chiffres de confiance réels, facettes à compteurs vivants, cartes de confiance.',
                'Fiche en drawer : à quoi ça sert, identité, structure avec les vrais types de colonnes, traçabilité amont/aval, actions.'] },
            { v: '3.3.0', d: '2026-07-22', t: 'Confort de saisie & import en masse', items: [
                'Le défilement et le champ actif sont préservés à chaque modification.',
                'Usages « par application », import en masse de la gouvernance avec modèles pré-remplis, taux de remplissage jamais trompeurs, lineage par attribut lisible.'] },
            { v: '3.2.0', d: '2026-07-22', t: 'Sauvegarde & performances', items: [
                'Centre de sauvegarde permanent dans l\'en-tête.',
                'Correctif majeur de performance de la Gouvernance (graphes cycliques).'] },
            { v: '3.1.0', d: '2026-07-21', t: 'Passe UX écran par écran', items: [
                'Menu Gouvernance en 5 familles, sources enrichies, inspecteur en drawer, états vides guidants.'] },
            { v: '3.0.0', d: '2026-07-21', t: 'Refonte ergonomique V3', items: [
                'Jetons de design, barre de contexte, tableau de profil enrichi, drawer, tooltips, accessibilité.'] },
        ];
        function appVersionShort() { return APP_VERSION.replace(/\.0$/, ''); }
        function openVersionNotes() {
            const body = `<div class="dsect"><p class="text-[12px] text-slate-500">Chaque évolution de Studio Data porte un numéro de version <strong>majeur.mineur.correctif</strong> : le mineur augmente à chaque évolution fonctionnelle, le majeur pour les refontes d'ampleur.</p></div>` +
                APP_CHANGELOG.map(c2 => `<div class="dsect"><h4>v${c2.v} — ${escapeHTML(c2.t)} <span class="font-normal text-slate-400 text-[10px]">(${new Date(c2.d).toLocaleDateString('fr-FR')})</span></h4>
                    <ul class="text-[12px] text-slate-600 space-y-1 mt-1">${c2.items.map(it => `<li>• ${escapeHTML(it)}</li>`).join('')}</ul></div>`).join('');
            openUxDrawer({ sem: '', title: 'Studio Data — v' + appVersionShort(), sub: 'Notes de version', body, foot: '' });
        }
        (function () { const b2 = el('appVersionBadge'); if (b2) b2.textContent = 'v' + appVersionShort(); })();

